frappe.ui.form.on('Lastmile Services Master', {
    before_save: function(frm) {
        if (frm.doc.circuit_id) {
            frappe.db.get_doc('Feasibility', frm.doc.circuit_id).then(feasibility => {
                if (feasibility && feasibility.name === frm.doc.circuit_id && feasibility.lms_feasibility) {
                    feasibility.lms_feasibility.forEach(child => {
                        if (child.lms_supplier === "Feasible") {
                            frm.set_value('lms_feasibility_id', child.name);
                            frm.set_value('lms_feasibility_status', child.lms_status);
                        }
                    });
                }
            });
        }
    }
});

frappe.ui.form.on('Subscription', {
    refresh: function(frm) {
        // Add button to fetch Sales Orders
        frm.add_custom_button(__('Get Sales Orders'), function() {
            // Fetch Sales Order data with all required fields
            frappe.call({
                method: 'frappe.client.get_list',
                args: {
                    doctype: 'Sales Order',
                    fields: ['name', 'customer', 'customer_name', 'po_no', 'transaction_date', 'status'],
                    limit_page_length: 20
                },
                callback: function(r) {
                    if (r.message) {
                        // Create MultiSelectDialog
                        const dialog = new frappe.ui.form.MultiSelectDialog({
                            doctype: 'Sales Order',
                            target: frm,
                            setters: {},
                            primary_action_label: 'Select',
                            action: function(selected_items) {
                                frappe.msgprint(__('Selected {0} Sales Orders', [selected_items.length]));
                                // Process selected items here
                            },
                            get_query: function() {
                                return {
                                    filters: {
                                        'status': ['not in', ['Completed', 'Cancelled']]
                                    }
                                };
                            },
                            add_filters_group: false,
                            make_new: false
                        });

                        // Set the data with all required fields
                        dialog.data = r.message.map(order => ({
                            name: order.name,
                            customer_name: order.customer_name || order.customer,
                            po_no: order.po_no || '',
                            transaction_date: order.transaction_date,
                            status: order.status
                        }));

                        // Set columns with all required headings
                        dialog.columns = [
                            {
                                label: __('Sales Order No'),
                                fieldname: 'name',
                                fieldtype: 'Link',
                                options: 'Sales Order',
                                width: 120
                            },
                            {
                                label: __('Customer Name'),
                                fieldname: 'customer_name',
                                fieldtype: 'Data',
                                width: 150
                            },
                            {
                                label: __('Customer PO'),
                                fieldname: 'po_no',
                                fieldtype: 'Data',
                                width: 120
                            },
                            {
                                label: __('Date'),
                                fieldname: 'transaction_date',
                                fieldtype: 'Date',
                                width: 100
                            },
                            {
                                label: __('Status'),
                                fieldname: 'status',
                                fieldtype: 'Data',
                                width: 100
                            }
                        ];

                        // Additional safeguard to remove any remaining buttons
                        setTimeout(() => {
                            dialog.$wrapper.find('.btn-new').remove();
                            dialog.$wrapper.find('.btn-secondary').remove();
                        }, 100);

                        dialog.show();
                    }
                }
            });
        }).css({
            'background-color': '#000000',
            'border-color': '#000000',
            'color': '#ffffff',
            'font-weight': 'bold',
            'transition': 'background-color 0.3s ease'
        }).hover(
            function() { $(this).css('background-color', '#333333'); },
            function() { $(this).css('background-color', '#000000'); }
        );
    }
});

frappe.ui.form.on('Customer', {
    onload: function (frm) {
        frm.trigger('setup_customer_name_validation');
    },

    setup_customer_name_validation: function (frm) {
        setTimeout(() => {
            const input = frm.fields_dict.customer_name?.$wrapper?.find('input');
            if (!input || input.hasClass('autocomplete-attached')) return;

            input.addClass('autocomplete-attached');

            let debounceTimer;
            let lastFormatted = '';

            const normalize = str =>
                str.toLowerCase()
                    .replace(/\b(limited|ltd|private|pvt|inc|llp|plc|corp|corporation|co|coop|bank|enterprises|group|india)\b/g, '')
                    .replace(/[^a-z0-9 ]/g, '')
                    .replace(/\s+/g, ' ')
                    .trim();

            const checkForDuplicates = (formatted) => {
                const norm_input = normalize(formatted);
                frappe.call({
                    method: "frappe.client.get_list",
                    args: {
                        doctype: "Customer",
                        fields: ["customer_name"],
                        limit_page_length: 1000
                    },
                    callback: function (res) {
                        const matches = res.message.map(row => {
                            const norm = normalize(row.customer_name);
                            let score = 0;
                            if (norm === norm_input) score = 3;
                            else if (norm.startsWith(norm_input)) score = 2;
                            else if (norm.includes(norm_input)) score = 1;

                            return { ...row, score };
                        }).filter(row => row.score > 0);

                        matches.sort((a, b) => b.score - a.score);

                        if (matches.length > 0) {
                            frm.__customer_match_found = true;
                            frm.__customer_match_score = matches[0].score;
                            frappe.msgprint({
                                title: "🛑 Similar Customer Found",
                                message: `A similar customer already exists: <b>${matches[0].customer_name}</b>. Please write the full name or verify before saving.`,
                                indicator: 'red'
                            });
                        } else {
                            frm.__customer_match_found = false;
                            frappe.msgprint({
                                title: "✅ Safe to Proceed",
                                message: "No similar customer found. You can continue.",
                                indicator: 'green'
                            });
                        }
                    }
                });
            };

            // Auto-format while typing, but delay check
            input.on('input', function () {
                clearTimeout(debounceTimer);
                const caretPos = this.selectionStart;
                let val = this.value.replace(/\s{2,}/g, ' ').trimStart();
                let formatted = val
                    .toLowerCase()
                    .split(' ')
                    .map(w => w.charAt(0).toUpperCase() + w.slice(1))
                    .join(' ');

                input.val(formatted);
                this.setSelectionRange(caretPos, caretPos);
                frm.set_value('customer_name', formatted);
                lastFormatted = formatted;

                debounceTimer = setTimeout(() => {
                    if (formatted.length >= 2) checkForDuplicates(formatted);
                }, 800); // Popup after pause
            });

            // Trigger duplicate check on blur
            input.on('blur', function () {
                if (lastFormatted.length >= 2) {
                    checkForDuplicates(lastFormatted);
                }
            });
        }, 300);
    },

    validate: function (frm) {
        if (frm.__customer_match_found && frm.__customer_match_score >= 2) {
            frappe.msgprint({
                title: "⛔ Duplicate Detected",
                message: "A similar customer already exists. Please correct the name before saving.",
                indicator: 'red'
            });
            frappe.validated = false;
        }
    }
});

frappe.ui.form.on('Prospect', {
    onload: function (frm) {
        frm.trigger('setup_company_name_popup_validation');
    },

    validate: function (frm) {
        if (frm.doc._duplicate_found) {
            frappe.msgprint({
                title: "🛑 Duplicate Company Name Found",
                message: `A similar company already exists: <b>${frm.doc._duplicate_name}</b>. Please enter the full and unique company name.`,
                indicator: 'red'
            });
            frappe.validated = false;
        }
    },

    setup_company_name_popup_validation: function (frm) {
        setTimeout(() => {
            const input = frm.fields_dict.company_name?.$wrapper?.find('input');
            if (!input || input.hasClass('autocomplete-attached')) return;

            input.addClass('autocomplete-attached');

            // Auto-format while typing
            input.on('input', function () {
                let typed_value = input.val();
                typed_value = typed_value
                    .replace(/\s{2,}/g, ' ')
                    .trim()
                    .toLowerCase()
                    .split(' ')
                    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
                    .join(' ');
                frm.set_value('company_name', typed_value);
            });

            // Validate on blur
            input.on('blur', function () {
                const typed_value = frm.doc.company_name;

                if (!typed_value || typed_value.length < 2) {
                    frm.doc._duplicate_found = false;
                    frm.doc._duplicate_name = "";
                    return;
                }

                const normalize = str =>
                    str.toLowerCase()
                        .replace(/\b(limited|ltd|private|pvt|inc|llp|plc|corp|corporation|co|coop|bank|enterprises|group|india|urban)\b/g, '')
                        .replace(/[^a-z0-9 ]/g, '')
                        .replace(/\s+/g, ' ')
                        .trim();

                const norm_input = normalize(typed_value);

                frappe.call({
                    method: "frappe.client.get_list",
                    args: {
                        doctype: "Prospect",
                        fields: ["company_name"],
                        limit_page_length: 1000
                    },
                    callback: function (res) {
                        let found_match = null;

                        res.message.forEach(row => {
                            const norm_existing = normalize(row.company_name);
                            if (
                                norm_existing === norm_input ||
                                norm_existing.includes(norm_input) ||
                                norm_input.includes(norm_existing)
                            ) {
                                found_match = row.company_name;
                            }
                        });

                        if (found_match) {
                            frm.doc._duplicate_found = true;
                            frm.doc._duplicate_name = found_match;

                            frappe.msgprint({
                                title: "🛑 Similar Company Found",
                                message: `A similar company already exists: <b>${found_match}</b>. Please enter the full name or ensure it's unique.`,
                                indicator: 'red'
                            });
                        } else {
                            frm.doc._duplicate_found = false;
                            frm.doc._duplicate_name = "";

                            frappe.msgprint({
                                title: "✅ No Duplicate Found",
                                message: `You may proceed. No similar company was found.`,
                                indicator: 'green'
                            });
                        }
                    }
                });
            });
        }, 300);
    }
});

frappe.ui.form.on('Lead', {
    onload: function (frm) {
        frm.trigger('setup_company_name_autocomplete');
    },

    validate: function (frm) {
        if (frm.__duplicate_blocked) {
            frappe.throw(`🛑 A similar company already exists: <b>${frm.__matched_name}</b>.<br>Please write full name or select from suggestions.`);
        }
    },

    setup_company_name_autocomplete: function (frm) {
        setTimeout(() => {
            const input = frm.fields_dict.company_name?.$wrapper?.find('input');
            if (!input || input.hasClass('autocomplete-attached')) return;

            input.addClass('autocomplete-attached');

            let dropdown = $('<div class="company-suggestion-box"></div>').css({
                position: 'absolute',
                background: '#fff',
                border: '1px solid #ccc',
                'z-index': 1000,
                width: input.outerWidth(),
                'max-height': '200px',
                'overflow-y': 'auto',
                'border-radius': '4px',
                'box-shadow': '0 4px 8px rgba(0,0,0,0.1)'
            }).hide();

            let feedback = $('<div class="company-warning" style="margin-top:4px; font-size:90%;"></div>').hide();
            input.after(dropdown).after(feedback);

            let debounceTimer;

            input.on('input', function () {
                clearTimeout(debounceTimer);

                let typed_value = input.val();

                // Auto-clean and capitalize
                typed_value = typed_value
                    .replace(/\s{2,}/g, ' ')
                    .trim()
                    .toLowerCase()
                    .split(' ')
                    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
                    .join(' ');

                frm.set_value('company_name', typed_value);

                if (!typed_value || typed_value.length < 2) {
                    dropdown.empty().hide();
                    feedback.hide();
                    frm.__duplicate_blocked = false;
                    return;
                }

                debounceTimer = setTimeout(() => {
                    frappe.call({
                        method: "frappe.client.get_list",
                        args: {
                            doctype: "Prospect",
                            fields: ["company_name"],
                            limit_page_length: 1000
                        },
                        callback: function (res) {
                            dropdown.empty();
                            feedback.hide();
                            frm.__duplicate_blocked = false;
                            frm.__matched_name = null;

                            const normalize = str =>
                                str.toLowerCase()
                                    .replace(/\b(limited|ltd|private|pvt|inc|llp|plc|corp|corporation|co|coop|bank|enterprises|group|india|urban)\b/g, '')
                                    .replace(/[^a-z0-9 ]/g, '')
                                    .replace(/\s+/g, ' ')
                                    .trim();

                            const norm_input = normalize(typed_value);

                            let matches = res.message.map(row => {
                                const norm = normalize(row.company_name);
                                let score = 0;

                                if (norm === norm_input) score = 3;
                                else if (norm.startsWith(norm_input)) score = 2;
                                else if (norm.includes(norm_input)) score = 1;

                                return { ...row, score };
                            }).filter(row => row.score > 0);

                            matches.sort((a, b) => b.score - a.score);

                            if (matches.length > 0) {
                                frm.__duplicate_blocked = true;
                                frm.__matched_name = matches[0].company_name;

                                feedback
                                    .html(`🛑 A similar company already exists: <b>${matches[0].company_name}</b>. Please write full name or select.`)
                                    .css('color', 'red')
                                    .show();

                                matches.forEach(m => {
                                    $('<div class="company-option"></div>')
                                        .text(m.company_name)
                                        .css({
                                            padding: '6px 12px',
                                            cursor: 'pointer'
                                        })
                                        .hover(
                                            function () { $(this).css('background', '#f5f5f5'); },
                                            function () { $(this).css('background', '#fff'); }
                                        )
                                        .click(function () {
                                            frm.set_value('company_name', m.company_name);
                                            dropdown.empty().hide();
                                            feedback.hide();
                                            frm.__duplicate_blocked = false;
                                        })
                                        .appendTo(dropdown);
                                });

                                dropdown
                                    .css({
                                        top: input.position().top + input.outerHeight(),
                                        left: input.position().left,
                                        width: input.outerWidth()
                                    })
                                    .show();
                            } else {
                                feedback
                                    .html(`✅ No similar company found. Safe to create.`)
                                    .css('color', 'green')
                                    .show();
                                dropdown.hide();
                            }
                        }
                    });
                }, 300);
            });

            $(document).on('click', function (e) {
                if (!$(e.target).closest('.company-suggestion-box, input[data-fieldname="company_name"]').length) {
                    dropdown.hide();
                }
            });
        }, 300);
    }
});

frappe.ui.form.on('LMS Feasibility Partner', {
    onload(frm) {
        frm.trigger('setup_supplier_autocomplete');
        frm.trigger('setup_street_capitalization');
    },

    // Capitalize 'street' field while typing
    setup_street_capitalization(frm) {
        setTimeout(() => {
            const input = frm.fields_dict.street?.$wrapper?.find('textarea, input');
            if (!input || input.hasClass('street-capitalization-attached')) return;

            input.addClass('street-capitalization-attached');

            input.on('input', function () {
                const cursorPos = this.selectionStart;
                const formatted = format_text(this.value);
                if (this.value !== formatted) {
                    this.value = formatted;
                    this.setSelectionRange(cursorPos, cursorPos);
                }
            });
        }, 300);
    },

    // Supplier autocomplete and duplicate check
    setup_supplier_autocomplete(frm) {
        setTimeout(() => {
            const input = frm.fields_dict.supplier?.$wrapper?.find('input');
            if (!input || input.hasClass('autocomplete-attached')) return;

            input.addClass('autocomplete-attached');

            let dropdown = $('<div class="supplier-suggestion-box"></div>').css({
                position: 'absolute',
                background: '#fff',
                border: '1px solid #ccc',
                'z-index': 1000,
                width: input.outerWidth(),
                'max-height': '200px',
                'overflow-y': 'auto',
                'border-radius': '4px',
                'box-shadow': '0 4px 8px rgba(0,0,0,0.1)',
                'padding': '4px'
            }).hide();

            input.after(dropdown);

            let debounceTimer;

            const normalize = str =>
                str.toLowerCase()
                    .replace(/\b(limited|ltd|private|pvt|inc|llp|plc|corp|corporation|co|coop|bank|enterprises|group|india)\b/g, '')
                    .replace(/[^a-z0-9 ]/g, '')
                    .replace(/\s+/g, ' ')
                    .trim();

            // Capitalize + suggest duplicates
            input.on('input', function () {
                clearTimeout(debounceTimer);

                const cursorPos = this.selectionStart;
                const formatted = format_text(this.value);

                if (this.value !== formatted) {
                    this.value = formatted;
                    this.setSelectionRange(cursorPos, cursorPos);
                }

                if (!formatted || formatted.length < 2) {
                    dropdown.empty().hide();
                    return;
                }

                debounceTimer = setTimeout(() => {
                    frappe.call({
                        method: "frappe.client.get_list",
                        args: {
                            doctype: "LMS Feasibility Partner",
                            fields: ["supplier"],
                            limit_page_length: 1000
                        },
                        callback: function (res) {
                            dropdown.empty();
                            const norm_input = normalize(formatted);

                            let matches = res.message.map(row => {
                                const norm = normalize(row.supplier);
                                let score = 0;
                                if (norm === norm_input) score = 3;
                                else if (norm.startsWith(norm_input)) score = 2;
                                else if (norm.includes(norm_input)) score = 1;
                                return { ...row, score };
                            }).filter(row => row.score > 0);

                            matches.sort((a, b) => b.score - a.score);

                            if (matches.length > 0) {
                                $('<div class="supplier-header-msg"></div>')
                                    .html('🛑 <b>Duplicate values found:</b>')
                                    .css({
                                        padding: '6px 12px',
                                        color: '#d00',
                                        'font-weight': 'bold',
                                        'border-bottom': '1px solid #eee'
                                    })
                                    .appendTo(dropdown);

                                matches.forEach(m => {
                                    $('<div class="supplier-option disabled"></div>')
                                        .text(m.supplier)
                                        .css({
                                            padding: '6px 12px',
                                            color: '#888',
                                            cursor: 'not-allowed',
                                            'pointer-events': 'none',
                                            'font-style': 'italic'
                                        })
                                        .appendTo(dropdown);
                                });

                                dropdown
                                    .css({
                                        top: input.position().top + input.outerHeight(),
                                        left: input.position().left,
                                        width: input.outerWidth()
                                    })
                                    .show();
                            } else {
                                dropdown.hide();
                            }
                        }
                    });
                }, 300);
            });

            // Duplicate check on blur
            input.on('blur', function () {
                const raw = input.val();
                if (!raw || raw.length < 2) return;

                const formatted = format_text(raw);
                frm.set_value('supplier', formatted);

                const norm_input = normalize(formatted);

                frappe.call({
                    method: "frappe.client.get_list",
                    args: {
                        doctype: "LMS Feasibility Partner",
                        fields: ["supplier"],
                        limit_page_length: 1000
                    },
                    callback: function (res) {
                        const matches = (res.message || []).filter(row => {
                            const norm = normalize(row.supplier);
                            return (
                                norm === norm_input ||
                                norm.startsWith(norm_input) ||
                                norm.includes(norm_input)
                            );
                        });

                        if (matches.length > 0) {
                            frappe.msgprint({
                                title: "🛑 Possible Duplicate",
                                message: `A similar supplier exists: <b>${matches.map(m => m.supplier).join(", ")}</b><br>Please use a unique name.`,
                                indicator: 'red'
                            });
                        } else {
                            frappe.msgprint({
                                title: "✅ No Duplicate Found",
                                message: "This supplier name appears unique. Safe to proceed.",
                                indicator: 'green'
                            });
                        }
                    }
                });
            });

            // Hide dropdown on outside click
            $(document).on('click', function (e) {
                if (!$(e.target).closest('.supplier-suggestion-box, input[data-fieldname="supplier"]').length) {
                    dropdown.hide();
                }
            });
        }, 300);
    }
});

// Utility: Capitalize each word and after hyphen
function format_text(str) {
    return str
        .toLowerCase()
        .replace(/\s{2,}/g, ' ')
        .split(/(\s+|\-)/)
        .map(word =>
