        )
        .join('');
}

frappe.ui.form.on('Supplier', {
    onload(frm) {
        frm.trigger('setup_supplier_name_autocomplete');
    },

    setup_supplier_name_autocomplete(frm) {
        setTimeout(() => {
            const input = frm.fields_dict.supplier_name?.$wrapper?.find('input');
            if (!input || input.hasClass('autocomplete-attached')) return;

            input.addClass('autocomplete-attached');

            let dropdown = $('<div class="supplier-suggestion-box"></div>').css({
                position: 'absolute',
                background: '#fff',
                border: '1px solid #ccc',
                'z-index': 1000,
                width: input.outerWidth(),
                'max-height': '200px',
                'overflow-y': 'auto',
                'border-radius': '4px',
                'box-shadow': '0 4px 8px rgba(0,0,0,0.1)',
                'padding': '4px'
            }).hide();

            input.after(dropdown);

            let debounceTimer;

            const normalize = str =>
                str.toLowerCase()
                    .replace(/\b(limited|ltd|private|pvt|inc|llp|plc|corp|corporation|co|coop|bank|enterprises|group|india)\b/g, '')
                    .replace(/[^a-z0-9 ]/g, '')
                    .replace(/\s+/g, ' ')
                    .trim();

            input.on('input', function () {
                clearTimeout(debounceTimer);

                const cursorPos = this.selectionStart;
                const formatted = format_text(this.value);

                if (this.value !== formatted) {
                    this.value = formatted;
                    this.setSelectionRange(cursorPos, cursorPos);
                }

                if (!formatted || formatted.length < 2) {
                    dropdown.empty().hide();
                    return;
                }

                debounceTimer = setTimeout(() => {
                    frappe.call({
                        method: "frappe.client.get_list",
                        args: {
                            doctype: "Supplier",
                            fields: ["supplier_name"],
                            limit_page_length: 1000
                        },
                        callback: function (res) {
                            dropdown.empty();
                            const norm_input = normalize(formatted);

                            let matches = res.message.map(row => {
                                const norm = normalize(row.supplier_name);
                                let score = 0;
                                if (norm === norm_input) score = 3;
                                else if (norm.startsWith(norm_input)) score = 2;
                                else if (norm.includes(norm_input)) score = 1;
                                return { ...row, score };
                            }).filter(row => row.score > 0);

                            matches.sort((a, b) => b.score - a.score);

                            if (matches.length > 0) {
                                $('<div class="supplier-header-msg"></div>')
                                    .html('🛑 <b>Duplicate values found:</b>')
                                    .css({
                                        padding: '6px 12px',
                                        color: '#d00',
                                        'font-weight': 'bold',
                                        'border-bottom': '1px solid #eee'
                                    })
                                    .appendTo(dropdown);

                                matches.forEach(m => {
                                    $('<div class="supplier-option disabled"></div>')
                                        .text(m.supplier_name)
                                        .css({
                                            padding: '6px 12px',
                                            color: '#888',
                                            cursor: 'not-allowed',
                                            'pointer-events': 'none',
                                            'font-style': 'italic'
                                        })
                                        .appendTo(dropdown);
                                });

                                dropdown
                                    .css({
                                        top: input.position().top + input.outerHeight(),
                                        left: input.position().left,
                                        width: input.outerWidth()
                                    })
                                    .show();
                            } else {
                                dropdown.hide();
                            }
                        }
                    });
                }, 300);
            });

            input.on('blur', function () {
                const raw = input.val();
                if (!raw || raw.length < 2) return;

                const formatted = format_text(raw);
                frm.set_value('supplier_name', formatted);

                const norm_input = normalize(formatted);

                frappe.call({
                    method: "frappe.client.get_list",
                    args: {
                        doctype: "Supplier",
                        fields: ["supplier_name"],
                        limit_page_length: 1000
                    },
                    callback: function (res) {
                        const matches = (res.message || []).filter(row => {
                            const norm = normalize(row.supplier_name);
                            return (
                                norm === norm_input ||
                                norm.startsWith(norm_input) ||
                                norm.includes(norm_input)
                            );
                        });

                        if (matches.length > 0) {
                            frappe.msgprint({
                                title: "🛑 Possible Duplicate",
                                message: `A similar supplier exists: <b>${matches.map(m => m.supplier_name).join(", ")}</b><br>Please use a unique name.`,
                                indicator: 'red'
                            });
                        } else {
                            frappe.msgprint({
                                title: "✅ No Duplicate Found",
                                message: "This supplier name appears unique. Safe to proceed.",
                                indicator: 'green'
                            });
                        }
                    }
                });
            });

            $(document).on('click', function (e) {
                if (!$(e.target).closest('.supplier-suggestion-box, input[data-fieldname="supplier_name"]').length) {
                    dropdown.hide();
                }
            });
        }, 300);
    }
});

// Utility function: Capitalize each word and after hyphens
function format_text(str) {
    return str
        .toLowerCase()
        .replace(/\s{2,}/g, ' ')
        .split(/(\s+|\-)/)
        .map(word =>
            /^[a-z]/.test(word) ? word.charAt(0).toUpperCase() + word.slice(1) : word
        )
        .join('');
}

