            return str
                .toLowerCase()
                .replace(/\s{2,}/g, ' ')
                .split(/(\s+|\-)/) // split by space and hyphen while retaining delimiters
                .map(part => /^[a-z]/.test(part) ? part.charAt(0).toUpperCase() + part.slice(1) : part)
                .join('');
        };

        fields.forEach(fieldname => {
