frappe.ui.form.on('Stock Management', {
    setup: function(frm) {
        if (!frm.doc.stock_activities) {
            frm.set_value('stock_activities', []);
        }
    },

    refresh: function(frm) {
        frm.toggle_display('activity_section', true);
        frm.toggle_display('activity_html', true);
        update_activity_display(frm);
    },

    status: function(frm) {
        if (!frm.doc.status) return;

        const last_activity = frm.doc.stock_activities?.slice(-1)[0];
        if (last_activity && last_activity.activity === frm.doc.status) return;

        frm.add_child('stock_activities', {
            activity: frm.doc.status,
            timestamp: frappe.datetime.now_datetime()
        });

        frm.refresh_field('stock_activities');
        update_activity_display(frm);
    }
});

function get_status_color(status) {
    switch(status) {
        case 'Stock Requested': return '#ec4899'; // Pink
        case 'Stock Reserved': return '#f59e0b'; // Orange
        case 'Update Serial/ SIM No': return '#3b82f6'; // Blue
        case 'Stock Delivered': return '#10b981'; // Green
        case 'Stock Delivery In-Process': return '#facc15'; // Yellow
        case 'Stock Unreserved': return '#6b7280'; // Grey
        default: return '#d1d5db'; // Light gray fallback
    }
}

function update_activity_display(frm) {
    const activities = frm.doc.stock_activities || [];

    const html = `
        <div class="activity-container" style="
            max-height: 300px;
            overflow-y: auto;
            padding: 10px;
            background: #f9fafb;
            border-radius: 8px;
            border: 1px solid #e5e7eb;
        ">
            ${activities.length ? 
                activities.slice().reverse().map(activity => {
                    const dateTime = frappe.datetime.str_to_user(activity.timestamp).split(' ');
                    const date = dateTime[0];
                    const time = dateTime[1];
                    const color = get_status_color(activity.activity);

                    return `
                        <div class="activity-item" style="
                            padding: 12px;
                            margin-bottom: 8px;
                            background: white;
                            border-left: 4px solid #3b82f6;
                            border-radius: 4px;
                            font-size: 12px;
                        ">
                            <button style="
                                background-color: ${color};
                                color: white;
                                border: none;
                                padding: 4px 12px;
                                border-radius: 9999px;
                                margin-right: 8px;
                                font-weight: bold;
                                font-size: 12px;
                            ">
                                ${activity.activity}
                            </button>
                            ${activity.activity} on Date: <strong>${date}</strong>, Time: <strong>${time}</strong>
                        </div>
                    `;
                }).join('') : 
                `<div style="color: #9ca3af; text-align: center; padding: 16px; font-size: 12px;">
                    No activities recorded yet
                </div>`
            }
        </div>
    `;

    frm.set_df_property('activity_html', 'options', html);
    frm.refresh_field('activity_html');
}

