frappe.ui.form.on('LMS Services Master', {
    refresh: function(frm) {
        // Remove any existing duplicate buttons first
        $('.lms-service-btn-group').remove();

        if (!frm.is_new()) {
            // Create the button HTML structure with a unique class
            let button_html = `
                <div class="btn-group lms-service-btn-group" style="margin-left: 5px;">
                    <button class="btn btn-sm btn-default dropdown-toggle" 
                        style="background-color: #000; color: #fff; border: 1px solid #000; width: 150px;" 
                        data-toggle="dropdown">
                        <strong style="width: 100%; text-align: center;">LMS Service</strong>
                        <span class="caret"></span>
                    </button>
                    <ul class="dropdown-menu" style="min-width: 150px; width: 150px; padding: 5px 0;">
                        <li style="margin-bottom: 8px;">
                            <a href="#" class="po-request" style="display: flex; align-items: center; padding: 8px 15px; text-decoration: none;">
                                <i class="fa fa-file-text-o" style="margin-right: 8px;"></i> PO Request
                            </a>
                        </li>
                        <li>
                            <a href="#" class="po-cancel" style="display: flex; align-items: center; padding: 8px 15px; text-decoration: none;">
                                <i class="fa fa-times" style="margin-right: 8px;"></i> PO Cancel
                            </a>
                        </li>
                    </ul>
                </div>
            `;

            // Add the button to the form
            let $button_group = $(button_html);
            frm.page.btn_primary.before($button_group);

            // PO Request click handler
            $button_group.on('click', '.po-request', function(e) {
                e.preventDefault();

                // Validate child table exists and has items
                if (!frm.doc.lms_fesible_suppliers || frm.doc.lms_fesible_suppliers.length === 0) {
                    frappe.throw(__('Please add at least one item in the LMS Services Master Item table'));
                    return false;
                }

                // Get only selected items (where select = 1 and po_id is blank)
                let selectedItems = frm.doc.lms_fesible_suppliers.filter(row => row.select === 1 && !row.po_id);

                if (selectedItems.length === 0) {
                    // Check if any items are already processed
                    let alreadyProcessed = frm.doc.lms_fesible_suppliers.filter(row => row.select === 1 && row.po_id);
                    if (alreadyProcessed.length > 0) {
                        frappe.throw(__('PO Request already done for selected items'));
                    } else {
                        frappe.throw(__('Please select at least one item by checking the "select" checkbox'));
                    }
                    return false;
                }

                // Validate all selected items have suppliers
                let missingSuppliers = selectedItems.filter(row => !row.supplier);
                if (missingSuppliers.length > 0) {
                    frappe.throw(__('Please select Supplier for all selected items'));
                    return false;
                }

                // Show confirmation dialog
                frappe.confirm(
                    __('Are you sure you want to request Purchase Orders for the selected items?'),
                    function() {
                        // Yes button clicked - proceed with PO creation
                        createPurchaseOrders(frm, selectedItems);
                    },
                    function() {
                        // No button clicked - do nothing
                        frappe.show_alert(__('Purchase Order request cancelled'));
                    }
                );
            });

            // PO Cancel click handler
            $button_group.on('click', '.po-cancel', function(e) {
                e.preventDefault();
                frappe.msgprint(__('PO Cancel functionality would go here'));
            });

            // Function to handle PO creation
            function createPurchaseOrders(frm, selectedItems) {
                // Group selected items by supplier
                let itemsBySupplier = {};
                selectedItems.forEach(row => {
                    if (!itemsBySupplier[row.supplier]) {
                        itemsBySupplier[row.supplier] = [];
                    }
                    itemsBySupplier[row.supplier].push(row);
                });

                // Create POs for each supplier with selected items only
                let po_names = [];
                let supplier_count = Object.keys(itemsBySupplier).length;
                let processed_count = 0;

                Object.keys(itemsBySupplier).forEach(supplier => {
                    let items = itemsBySupplier[supplier];

                    // Create base PO items
                    let po_items = items.map(item => ({
                        'item_code': item.item_code,
                        'item_name': item.item_name,
                        'qty': item.qty,
                        'rate': item.item_rate,
                        'schedule_date': frappe.datetime.get_today(),
                        'lms_id': frm.doc.name,
                        'circuit_id': frm.doc.circuit_id
                    }));

                    // Add security_deposit item if it has value
                    if (items[0].security_deposit) {
                        po_items.push({
                            'item_code': 'STO-ITEM-2025-04962',
                            'item_name': 'Security Deposit',
                            'qty': 1,
                            'rate': items[0].security_deposit,
                            'schedule_date': frappe.datetime.get_today(),
                            'lms_id': frm.doc.name,
                            'circuit_id': frm.doc.circuit_id
                        });
                    }

                    // Add otc item if it has value
                    if (items[0].otc) {
                        po_items.push({
                            'item_code': 'STO-ITEM-2025-04963',
                            'item_name': 'OTC',
                            'qty': 1,
                            'rate': items[0].otc,
                            'schedule_date': frappe.datetime.get_today(),
                            'lms_id': frm.doc.name,
                            'circuit_id': frm.doc.circuit_id
                        });
                    }

                    let po = {
                        'doctype': 'Purchase Order',
                        'supplier': supplier,
                        'schedule_date': frappe.datetime.get_today(),
                        'custom_po_category': items[0].po_category,
                        'project': frm.doc.parent_project,
                        'items': po_items
                    };

                    frappe.call({
                        method: 'frappe.client.insert',
                        args: { 'doc': po },
                        callback: function(response) {
                            if (!response.exc) {
                                // Update po_id and status in child table for each item
                                let promises = items.map(item => {
                                    return frappe.call({
                                        method: 'frappe.client.set_value',
                                        args: {
                                            'doctype': 'LMS Services Master Item',
                                            'name': item.name,
                                            'fieldname': {
                                                'po_id': response.message.name,
                                                'status': 'Requested' // Update status to "Requested"
                                            }
                                        },
                                        async: false
                                    });
                                });

                                // Wait for all updates to complete
                                Promise.all(promises).then(() => {
                                    po_names.push(response.message.name);
                                    processed_count++;

                                    // Show final message when all POs are created
                                    if (processed_count === supplier_count) {
                                        frappe.msgprint({
                                            title: __('Purchase Order Requested'),
                                            indicator: 'green',
                                            message: __('Purchase Order has been successfully requested for the selected items.') + 
                                                     (po_names.length > 0 ? '<br><br>' + __('<b>PO Numbers:</b> {0}', [po_names.join(', ')]) : '')
                                        });

                                        // Refresh the form to show updated po_ids and status
                                        frm.refresh();
                                    }
                                });
                            } else {
                                frappe.msgprint({
                                    title: __('Error'),
                                    indicator: 'red',
                                    message: __('Failed to create Purchase Order: {0}', [response.exc])
                                });
                            }
                        },
                        freeze: true,
                        freeze_message: __('Requesting Purchase Order for supplier {0}...', [supplier])
                    });
                });
            }
        }
    }
});

