frappe.ui.form.on('Site', {
    refresh: async function(frm) {
        // Only show the button if lms_stage is "Pending"
        if (frm.doc.lms_stage !== "Pending") return;

        const allowedStatuses = ['Feasible', 'High Commercials'];

        // Filter valid vendors
        const validVendors = (frm.doc.lms_vendor || []).filter(row =>
            allowedStatuses.includes(row.lms_status)
        );

        if (validVendors.length === 0) return;

        const hasLMSRequested = validVendors.some(row => row.lms_requested_id);
        const buttonLabel = hasLMSRequested ? 'LMS Requested' : 'LMS Request';

        const btn = frm.add_custom_button(buttonLabel, function () {
            if (hasLMSRequested) {
                frappe.msgprint(__('LMS Request already created.'));
                return;
            }

            frappe.confirm(
                'Are you sure you want to create an LMS Request?',
                async () => {
                    await frm.reload_doc(); // Ensure you have the latest data

                    const updatedValidVendors = (frm.doc.lms_vendor || []).filter(row =>
                        allowedStatuses.includes(row.lms_status) && !row.lms_requested_id
                    );

                    const feasibleVendors = updatedValidVendors.filter(row => row.lms_status === 'Feasible');

                    if (feasibleVendors.length === 0) {
                        frappe.msgprint(__('No feasible vendors found'));
                        return;
                    }

                    // Prepare data for LMS Request
                    const feasibleSuppliers = feasibleVendors.map(vendor => ({
                        lms_feasibility_partner: vendor.lms_supplier,
                        lms_feasibility_status: vendor.lms_status,
                        supplier_contact: vendor.supplier_contact,
                        bandwith_type: vendor.bandwith_type,
                        media: vendor.media,
                        support_mode: vendor.support_mode,
                        email_id: vendor.email_id,
                        mobile: vendor.mobile,
                        static_ip: vendor.static_ip,
                        bandwidth: vendor.bandwidth,
                        billing_mode: vendor.billing_mode,
                        billing_terms: vendor.billing_terms,
                        feasibility_otc: vendor.otc,
                        validity: vendor.validity,
                        feasibility_security_deposit: vendor.security_deposit,
                        feasibility_mrc: vendor.mrc,
                        feasibility_arc: vendor.arc,
                        feasibility_static_ip_cost: vendor.static_ip_cost
                    }));

                    // Create LMS Request
                    frappe.call({
                        method: 'frappe.client.insert',
                        args: {
                            doc: {
                                doctype: 'LMS Request',
                                circuit_id: frm.doc.name,
                                lms_fesible_suppliers: feasibleSuppliers
                            }
                        },
                        callback: function (res) {
                            if (res.message) {
                                const lmsRequestName = res.message.name;

                                // Update vendors with LMS Requested ID
                                frappe.call({
                                    method: 'frappe.client.set_value',
                                    args: {
                                        doctype: 'Site',
                                        name: frm.doc.name,
                                        fieldname: {
                                            lms_stage: 'LMS Initiated'
                                        }
                                    },
                                    callback: function () {
                                        // Update child table rows
                                        (frm.doc.lms_vendor || []).forEach(row => {
                                            if (row.lms_status === 'Feasible' && !row.lms_requested_id) {
                                                frappe.model.set_value(row.doctype, row.name, 'stage', 'LMS Initiated');
                                                frappe.model.set_value(row.doctype, row.name, 'lms_requested_id', lmsRequestName);
                                            }
                                        });

                                        frappe.msgprint({
                                            title: __('Success'),
                                            message: __('LMS Request created and LMS Stage updated.'),
                                            indicator: 'green'
                                        });

                                        frm.reload_doc(); // Reload after update to reflect changes
                                    }
                                });
                            }
                        }
                    });
                },
                () => {
                    frappe.msgprint(__('LMS Request cancelled.'));
                }
            );
        });

        // Button style
        btn.css({
            "background-color": "#dc3545",
            "color": "#fff",
            "border": "1px solid #c82333",
            "font-weight": "bold"
        });

        btn.addClass("btn btn-sm");
    }
});

