frappe.ui.form.on('LMS Request', {
    refresh(frm) {
        disable_select_if_lms_exists(frm);

        const buttonLabel = frm.doc.lms_fesible_suppliers?.some(row => row.lms_id) ? 'LMS ID Created' : 'Create LMS ID';

        frm.add_custom_button(__(buttonLabel), function () {
            frappe.confirm(
                __('Are you sure you want to create LMS ID for the selected suppliers?'),
                async () => {
                    const items = frm.doc.lms_fesible_suppliers || [];

                    let createdFeasible = 0;
                    let createdHighCommercials = 0;
                    let skippedNotFeasible = 0;
                    let skippedBlankStatus = 0;
                    let skippedExisting = 0;
                    let skippedMissingSupplier = 0; // NEW

                    const validSelections = items.filter(row => row.select === 1);

                    if (validSelections.length === 0) {
                        frappe.msgprint({
                            title: __('Validation'),
                            message: __('⚠️ Please select at least one feasible supplier to create LMS ID.'),
                            indicator: 'orange'
                        });
                        return;
                    }

                    for (const row of validSelections) {
                        const feasibility = row.lms_feasibility_status;

                        if (row.lms_id) {
                            skippedExisting++;
                            frappe.msgprint({
                                title: __('Already Exists'),
                                message: __('LMS ID already exists for <b>{0}</b>. Skipping creation.', [row.lms_feasibility_partner]),
                                indicator: 'blue'
                            });
                            frappe.meta.get_docfield(row.doctype, 'select', frm.doc.name).read_only = 1;
                            continue;
                        }

                        if (!feasibility) {
                            skippedBlankStatus++;
                            continue;
                        }

                        if (feasibility === 'Not Feasible') {
                            skippedNotFeasible++;
                            continue;
                        }

                        if (['Feasible', 'High Commercials'].includes(feasibility)) {

                            // ✅ NEW: Check if supplier exists
                            const supplier_exists = await frappe.db.exists('Supplier', row.lms_feasibility_partner);
                            if (!supplier_exists) {
                                skippedMissingSupplier++;
                                frappe.msgprint({
                                    title: __('Supplier Not Found'),
                                    message: __('⚠️ Supplier <b>{0}</b> does not exist in Supplier master. Skipping LMS ID creation.', [row.lms_feasibility_partner]),
                                    indicator: 'red'
                                });
                                continue;
                            }

                            const new_doc = frappe.model.get_new_doc('Lastmile Services Master');

                            new_doc.supplier = row.lms_feasibility_partner;
                            new_doc.bandwith_type = row.bandwith_type;
                            new_doc.lms_bandwith = row.bandwidth;
                            new_doc.media = row.media;
                            new_doc.customer = frm.doc.customer;
                            new_doc.circuit_id = frm.doc.circuit_id;
                            new_doc.site = frm.doc.site_name;
                            new_doc.solution = frm.doc.solution;
                            new_doc.site_type = frm.doc.site_type;
                            new_doc.primary_plan = frm.doc.primary_plan;
                            new_doc.secondary_plan = frm.doc.secondary_plan;
                            new_doc.payment_mode = row.billing_mode;
                            new_doc.security_deposit = row.security_deposit;
                            new_doc.billing_terms = row.billing_terms;
                            new_doc.billing_mode = row.billing_mode;
                            new_doc.validity = row.validity;
                            new_doc.parent_project = frm.doc.parent_project;
                            new_doc.lms_request_id = frm.doc.name;
                            new_doc.lms_requested_date = frappe.datetime.get_today();

                            const po_item = frappe.model.add_child(new_doc, 'LMS PO Item', 'table_djyj');
                            po_item.item_code = row.bandwidth;
                            po_item.item_rate = row.mrc;
                            po_item.qty = row.po_qty || 1;
                            po_item.total_amount = row.mrc * po_item.qty;

                            if (row.security_deposit) {
                                const deposit_item = frappe.model.add_child(new_doc, 'LMS PO Item', 'table_djyj');
                                deposit_item.item_code = 'STO-ITEM-2025-04962';
                                deposit_item.item_rate = row.security_deposit;
                                deposit_item.qty = 1;
                                deposit_item.total_amount = row.security_deposit;
                            }

                            if (row.otc) {
                                const otc_item = frappe.model.add_child(new_doc, 'LMS PO Item', 'table_djyj');
                                otc_item.item_code = 'STO-ITEM-2025-04963';
                                otc_item.item_rate = row.otc;
                                otc_item.qty = 1;
                                otc_item.total_amount = row.otc;
                            }

                            if (row.static_ip_cost) {
                                const static_ip_item = frappe.model.add_child(new_doc, 'LMS PO Item', 'table_djyj');
                                static_ip_item.item_code = 'STO-ITEM-2025-04965';
                                static_ip_item.item_rate = row.static_ip_cost;
                                static_ip_item.qty = 1;
                                static_ip_item.total_amount = row.static_ip_cost;
                            }

                            try {
                                const response = await frappe.call({
                                    method: 'frappe.client.insert',
                                    args: { doc: new_doc }
                                });

                                if (response && response.message) {
                                    await frappe.model.set_value(row.doctype, row.name, 'lms_id', response.message.name);
                                    frappe.meta.get_docfield(row.doctype, 'select', frm.doc.name).read_only = 1;

                                    if (feasibility === 'Feasible') {
                                        createdFeasible++;
                                    } else if (feasibility === 'High Commercials') {
                                        createdHighCommercials++;
                                    }
                                }
                            } catch (error) {
                                console.error(`❌ Failed to create LMS for ${row.lms_feasibility_partner}`, error);
                                frappe.msgprint(__('Failed to create LMS ID for ') + row.lms_feasibility_partner);
                            }
                        }
                    }

                    await frm.save();
                    frm.refresh_field('lms_fesible_suppliers');

                    let messageParts = [];

                    if (createdFeasible > 0) {
                        messageParts.push(`✅ LMS ID created for <b>${createdFeasible}</b> Feasible record(s).`);
                    }
                    if (createdHighCommercials > 0) {
                        messageParts.push(`✅ LMS ID created for <b>${createdHighCommercials}</b> High Commercials record(s).`);
                    }
                    if (skippedNotFeasible > 0 || skippedBlankStatus > 0) {
                        messageParts.push(`⚠️ <b>${skippedNotFeasible}</b> record(s) were 'Not Feasible' and <b>${skippedBlankStatus}</b> had blank status — LMS ID not created.`);
                    }
                    if (skippedExisting > 0) {
                        messageParts.push(`ℹ️ <b>${skippedExisting}</b> record(s) already had LMS ID — skipped.`);
                    }
                    if (skippedMissingSupplier > 0) {
                        messageParts.push(`❌ <b>${skippedMissingSupplier}</b> record(s) skipped — Supplier not found in master.`);
                    }

                    if (messageParts.length > 0) {
                        frappe.msgprint({
                            title: __('LMS ID Creation Summary'),
                            message: messageParts.join('<br>'),
                            indicator: (createdFeasible + createdHighCommercials > 0) ? 'green' : 'orange'
                        });
                    }

                    const btn = frm.custom_buttons['Create LMS ID'] || frm.custom_buttons['LMS ID Created'];
                    if (btn) {
                        $(btn).text('LMS ID Created');
                    }
                },
                () => {
                    frappe.msgprint(__('LMS ID creation was cancelled.'));
                }
            );
        });

        setTimeout(() => {
            const btn = frm.custom_buttons['Create LMS ID'] || frm.custom_buttons['LMS ID Created'];
            if (btn) {
                $(btn).css({
                    'background-color': 'black',
                    'color': 'white',
                    'font-weight': 'bold'
                });
            }
        }, 100);
    }
});

