frappe.ui.form.on('Installation Master', {
    refresh: function(frm) {
        // Get all child rows with 'Open' status
        const open_rows = (frm.doc.engineer_visit || []).filter(row => row.engineer_status === 'Open');

        if (open_rows.length > 0) {
            frm.add_custom_button(__('Engineer Visit'), function () {
                // Confirmation dialog before proceeding
                frappe.confirm(
                    __('Are you sure you want to create the Maintenance Visit records for these open engineer visits?'),
                    function() {
                        // User confirmed, proceed with record creation

                        const promises = [];
                        const initial_total_cost = parseFloat(frm.doc.total_engineer_visit_cost || 0); // Retrieve existing total cost

                        open_rows.forEach(row => {
                            // Skip if already linked
                            if (row.maintenance_visit_id) return;

                            // Create new Maintenance Visit
                            const doc = {
                                doctype: 'Maintenance Visit',
                                custom_circuit_id: frm.doc.circuit_id,
                                custom_site_contact_person: frm.doc.site_contact_person,
                                custom_site_contact_mobile: frm.doc.site_contact_mobile,
                                custom_engineer: row.engineer,
                                custom_engineer_mobile: row.engineer_mobile,
                                custom_field_engineer_name: row.field_engineer_name,
                                custom_field_engineer_mobile: row.field_engineer_mobile,
                                mntc_date: row.engineer_vist_datetime,
                                custom_visit_type: row.visit_type,
                                contact_email: row.engineer_contact_email,
                                custom_engineer_visit_cost: row.engineer_visit_cost,
                                installation_status: 'Installation In-process',
                                purposes: [{
                                    purpose: 'Engineer Visit',
                                    work_done: 'Engineer site visit',
                                    item_code: 'STO-ITEM-2025-05011',
                                    description: 'Engineer site visit charges',
                                    qty: 1,
                                    uom: 'Nos',
                                    service_person: row.engineer || row.field_engineer_name
                                }]
                            };

                            promises.push(
                                new Promise(resolve => {
                                    frappe.call({
                                        method: 'frappe.client.insert',
                                        args: { doc },
                                        callback: function (res) {
                                            if (res.message) {
                                                row.maintenance_visit_id = res.message.name;
                                                row.engineer_status = 'Engineer Assigned';
                                                resolve();
                                            }
                                        }
                                    });
                                })
                            );
                        });

                        // After all records are created, update the total engineer visit cost
                        Promise.all(promises).then(() => {
                            // Calculate the new total cost by adding all the engineer visit costs
                            let total_cost = initial_total_cost;

                            open_rows.forEach(row => {
                                // Only add the cost if the maintenance_visit_id is set (i.e., the record was created)
                                if (row.maintenance_visit_id) {
                                    total_cost += parseFloat(row.engineer_visit_cost || 0);
                                }
                            });

                            // Update the Installation Master total cost field
                            frm.set_value('total_engineer_visit_cost', total_cost);

                            // Manually mark the document as dirty to trigger save
                            frm.dirty();
                            frm.save().then(() => {
                                frappe.show_alert({ message: 'Maintenance Visits created successfully.', indicator: 'green' });
                                frm.refresh_field('engineer_visit');
                            });
                        });

                    },
                    function() {
                        // User canceled the action, do nothing
                        frappe.show_alert({ message: 'Action canceled.', indicator: 'red' });
                    }
                );
            }).css({
                'background-color': 'black',
                'color': 'white',
                'font-weight': 'bold',
                'border': 'none',
                'padding': '10px 20px',
                'border-radius': '5px'
            });
        }
    }
});

