function create_provisioning_record(frm) {
    // Check if provisioning record already exists
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Provisioning',
            filters: {
                'maintenance_id': frm.doc.name
            },
            fields: ['name']
        },
        callback: function(r) {
            if (r.message && r.message.length > 0) {
                // Provisioning record already exists - no action needed
            } else {
                // Create new Provisioning record with completion datetime
                let provisioning = {
                    'doctype': 'Provisioning',
                    'circuit_id': frm.doc.custom_circuit_id,
                    'maintenance_id': frm.doc.name,
                    'installation_completion_datetime': frm.doc.custom_completed_datetime
                };

                frappe.call({
                    method: 'frappe.client.insert',
                    args: {
                        'doc': provisioning
                    },
                    callback: function(response) {
                        if (!response.exc) {
                            // Update Maintenance Visit completion_status
                            frappe.call({
