function calculate_single_field(frm, cdt, cdn, feasibility_field, actual_field, negotiated_field) {
    let row = locals[cdt][cdn];

    // Accept 0 as valid input
    if (row[feasibility_field] != null && row[actual_field] != null) {
        row[negotiated_field] = row[feasibility_field] - row[actual_field];
    } else {
        row[negotiated_field] = null;
    }

    // Refresh the child table
    frm.fields_dict['lms_fesible_suppliers'].grid.refresh();
}

