// ────────────────────────────────────────────
// 3️⃣ Show/hide columns based on custom_expense_type
function toggle_columns(frm) {
  const isLocal = frm.doc.custom_expense_type === 'Local EXP';
  const grid    = frm.fields_dict.expenses.grid;

  // Local only
  grid.toggle_display('meeting',            isLocal);
  grid.toggle_display('mode',               isLocal);
  grid.toggle_display('km',                 isLocal);

  // Always visible
  grid.toggle_display('expense_date',       true);
  grid.toggle_display('expense_claim_type', true);
  grid.toggle_display('customer',           true);
  grid.toggle_display('amount',             true);

  // Attach Bill hidden on Local, shown on Tour
  grid.toggle_display('attach_bill',        !isLocal);

  // Also set field‐level hidden property for child
  frappe.model.set_df_property(
    'Expense Claim Detail', 'attach_bill', 'hidden', isLocal
  );

  // Refresh the table layout
  frm.refresh_field('expenses');
}

// ────────────────────────────────────────────
// 4️⃣ Default “Expense Claim Type” on new/existing rows
function default_one_row(frm, cdt, cdn) {
  const row = locals[cdt][cdn];
  if (frm.doc.custom_expense_type === 'Local EXP') {
    frappe.model.set_value(cdt, cdn, 'expense_claim_type', 'Local Conveyance-CCR');
  }
}

function default_all_rows(frm) {
  // only run when Local EXP
  if (frm.doc.custom_expense_type !== 'Local EXP') return;

  (frm.doc.expenses || []).forEach(row => {
    // row.doctype === "Expense Claim Detail", row.name is the docname
    frappe.model.set_value(
      row.doctype,
      row.name,
      'expense_claim_type',
      'Local Conveyance-CCR'
    );
  });

  // re-render the child‐table so the UI shows the new link values
  frm.refresh_field('expenses');
}

// ────────────────────────────────────────────
// 5️⃣ Calculate each row’s amount (Local only)
function recalc_row(frm, cdt, cdn) {
  const row = locals[cdt][cdn];

  // Skip for Tour EXP
  if (frm.doc.custom_expense_type !== 'Local EXP') {
    return recalc_grand_total(frm);
  }

  if (!row.km || !row.mode) {
    frappe.model.set_value(cdt, cdn, 'amount', 0);
    return recalc_grand_total(frm);
  }

  const rate = row.mode === 'Two Wheeler'
    ? 4
    : row.mode === 'Four Wheeler'
      ? 8
      : 0;

  frappe.model.set_value(cdt, cdn, 'amount', row.km * rate);
  recalc_grand_total(frm);
}

// ────────────────────────────────────────────
// 6️⃣ Sum & cap total at ₹10,000 (Local only)
function recalc_grand_total(frm) {
  let total = (frm.doc.expenses || []).reduce((sum, r) => {
    return sum + (parseFloat(r.amount) || 0);
  }, 0);

  if (frm.doc.custom_expense_type === 'Local EXP' && total > 10000) {
    frappe.msgprint('⚠️ Total Conveyance for Local EXP is capped at ₹10,000.');
    total = 10000;
  }

  frm.set_value('grand_total', total);
}

