        recalc_row(frm, cdt, cdn);
    },
    km: function(frm, cdt, cdn) {
        recalc_row(frm, cdt, cdn);
    },
    mode: function(frm, cdt, cdn) {
        recalc_row(frm, cdt, cdn);
    }
});

// Reset view: defaults, toggles, and totals
function reset_view(frm) {
    // apply defaults to all rows
    (frm.doc.expenses || []).forEach(function(row) {
        apply_defaults(frm, row.doctype, row.name);
    });

    recalc_grand_total(frm);

    // reset columns to default
    var grid = frm.fields_dict['expenses'] && frm.fields_dict['expenses'].grid;
    if (grid && typeof grid.setup_columns === 'function') {
        grid.setup_columns();
    }

    // show/hide based on type
    var type = frm.doc.custom_expense_type;
    var local = (type === 'Local EXP');
    var tour  = (type === 'Tour EXP');
    var localCols = ['expense_date','expense_claim_type','meeting','customer','mode','km','amount'];
    var tourCols  = ['expense_date','expense_claim_type','amount','attach_bill'];
    var allCols   = localCols.concat(tourCols);

    allCols.forEach(function(fn) {
        var show = (local && localCols.includes(fn)) || (tour && tourCols.includes(fn));
        if (grid && grid.set_column_disp) {
            grid.set_column_disp(fn, show);
        }
        frappe.model.set_df_property('Expense Claim Detail', fn, 'hidden', !show);
        frappe.model.set_df_property('Expense Claim Detail', fn, 'in_list_view', show);
        frappe.model.set_df_property('Expense Claim Detail', fn, 'in_preview', show);
    });

    frm.refresh_field('expenses');
}

// Clear and default a single row
function apply_defaults(frm, cdt, cdn) {
    var row = locals[cdt][cdn];
    var fields = ['expense_date','expense_claim_type','meeting','customer','mode','km','amount','attach_bill'];
    fields.forEach(function(fn) {
        frappe.model.set_value(cdt, cdn, fn, null);
    });
    var def = '';
    if (frm.doc.custom_expense_type === 'Local EXP') {
        def = 'Local Conveyance-CCR';
    } else if (frm.doc.custom_expense_type === 'Tour EXP') {
        def = 'Local Conveyance';
    }
    if (def) {
        frappe.model.set_value(cdt, cdn, 'expense_claim_type', def);
    }
}

// Recalculate a row's amount for Local EXP
function recalc_row(frm, cdt, cdn) {
    var row = locals[cdt][cdn];
    if (frm.doc.custom_expense_type !== 'Local EXP') {
        recalc_grand_total(frm);
        return;
    }
    var rate = row.mode === 'Two Wheeler' ? 4 : (row.mode === 'Four Wheeler' ? 8 : 0);
    var amt = (row.km || 0) * rate;
    frappe.model.set_value(cdt, cdn, 'amount', amt);
    recalc_grand_total(frm);
}

// Recalculate grand total and cap for Local EXP
function recalc_grand_total(frm) {
    var total = 0;
    (frm.doc.expenses || []).forEach(function(r) {
        total += parseFloat(r.amount) || 0;
    });
    if (frm.doc.custom_expense_type === 'Local EXP' && total > 10000) {
        frappe.msgprint('⚠️ Total Conveyance for Local EXP is capped at ₹10,000.');
        total = 10000;
    }
    frm.set_value('grand_total', total);
}


