frappe.ui.form.on('Provisioning', {

    // -----------------------------------
    // VALIDATE: STATUS + DATE + IP CHECKS
    // -----------------------------------
    validate: function(frm) {

        const has = v => v !== null && v !== undefined && String(v).trim() !== '';
        let hasL1 = has(frm.doc.lms_id_1);
        let hasL2 = has(frm.doc.lms_id_2);
        let newStatus = "Pending";

        let lmsType = (frm.doc.lms_type || "").toLowerCase();

        // ✅ Branch Router IP is required
        if (!frm.doc.branch_router_ip || frm.doc.branch_router_ip.trim() === "") {
            frappe.throw(__('Branch Router IP is required before saving.'));
        }

        // ✅ STATUS LOGIC
        if (lmsType.includes("no lms")) {
            newStatus = "Completed";
        }
        else if (lmsType.includes("single")) {
            newStatus = (hasL1 || hasL2) ? "Completed" : "Pending";
        }
        else if (lmsType.includes("dual")) {
            if (hasL1 && hasL2) {
                newStatus = "Completed";
            } else if (!hasL1 && !hasL2) {
                newStatus = "Pending";
            } else {
                newStatus = "Partially Completed";
            }
        }

        // ✅ Update status
        frm.set_value("status", newStatus);

        // ✅ DATE VALIDATION
        if (newStatus === "Completed" && !frm.doc.provisioning_date) {
            frappe.throw(__('Please enter the Provisioning Date before saving.'));
        }

        if (newStatus === "Partially Completed" && !frm.doc.provisioning_partially_completed_date) {
            frappe.throw(__('Please enter the Provisioning Partially Completed Date before saving.'));
        }

        // ✅ IP VALIDATION
        const fields = [
            ['atm_ip', 'ATM IP', false],
            ['branch_natted_ip', 'Branch Natted IP', true],
            ['branch_router_ip', 'Branch Router IP', false],
            ['branch_lane_series', 'Branch Lane Series', true],
            ['dc_static_ip', 'DC Static IP', false],
            ['dc_router_ip', 'DC Router IP', false],
            ['dc_secondary_static_ip', 'DC Secondary Static IP', false],
            ['dc_server_gateway_ip', 'DC Server Gateway IP', false],
            ['dc_server_ip', 'DC Server IP', false],
            ['dc_server_ip_2', 'DC Server IP 2', false],
            ['dr_static_ip', 'DR Static IP', false],
            ['dr_router_ip', 'DR Router IP', false],
            ['dr_secondary_static_ip', 'DR Secondary Static IP', false],
            ['dr_server_gateway_ip', 'DR Server Gateway IP', false],
            ['dr_server_ip', 'DR Server IP', false],
            ['dr_server_ip_2', 'DR Server IP 2', false],
            ['wan_static_ip_1', 'WAN Static IP 1', false],
            ['wan_gateway_ip_1', 'WAN Gateway IP 1', false],
            ['subnet_mask_1', 'Subnet Mask 1', false],
            ['wan_static_ip_2', 'WAN Static IP 2', false],
            ['wan_gateway_ip_2', 'WAN Gateway IP 2', false],
            ['subnet_mask_2', 'Subnet Mask 2', false]
        ];

        const ipv4_re = /^(25[0-5]|2[0-4][0-9]|1?[0-9]{1,2})(\.(25[0-5]|2[0-4][0-9]|1?[0-9]{1,2})){3}$/;
        const cidr_re = /^(25[0-5]|2[0-4][0-9]|1?[0-9]{1,2})(\.(25[0-5]|2[0-4][0-9]|1?[0-9]{1,2})){3}\/([0-9]|[1-2][0-9]|3[0-2])$/;

        for (let i = 0; i < fields.length; i++) {
            const fieldname = fields[i][0];
            const label = fields[i][1];
            const allowCidr = fields[i][2];

            const value = frm.doc[fieldname];
            if (value && !(ipv4_re.test(value) || (allowCidr && cidr_re.test(value)))) {
                frappe.msgprint({
                    title: "Invalid IP Address",
                    message: `${label} has an invalid IP format.`,
                    indicator: "red"
                });
                frappe.validated = false;
                break;
            }
        }
    },

    // -----------------------------------
    // REFRESH: LMS FILTERS
    // -----------------------------------
    refresh: function(frm) {
        frm.set_query("lms_id_2", function() {
            return {
                filters: frm.doc.lms_id_1 ? [["name", "!=", frm.doc.lms_id_1]] : []
            };
        });

        frm.set_query("lms_id_1", function() {
            return {
                filters: frm.doc.lms_id_2 ? [["name", "!=", frm.doc.lms_id_2]] : []
            };
        });
    },

    // -----------------------------------
    // LMS DUPLICATE PREVENTION
    // -----------------------------------
    lms_id_1: function(frm) {
        if (frm.doc.lms_id_2 && frm.doc.lms_id_1 === frm.doc.lms_id_2) {
            frm.set_value("lms_id_2", null);
            frappe.show_alert({ message: "LMS ID 2 cannot be the same as LMS ID 1.", indicator: "orange" });
        }
    },

    lms_id_2: function(frm) {
        if (frm.doc.lms_id_1 && frm.doc.lms_id_1 === frm.doc.lms_id_2) {
            frm.set_value("lms_id_2", null);
            frappe.show_alert({ message: "LMS ID 2 cannot be the same as LMS ID 1.", indicator: "orange" });
        }
    },

    // -----------------------------------
    // AFTER SAVE: UPDATE SITE + INSTALLATION MASTER
    // -----------------------------------
    after_save: function(frm) {

        if ((frm.doc.status === 'Completed' || frm.doc.status === 'Partially Completed') && frm.doc.circuit_id) {

            let site_updates = { provisioning_id: frm.doc.name };
            let installation_status = "";
            let confirmation_message = "";

            if (frm.doc.status === 'Completed') {
                site_updates.provisioning_date = frm.doc.provisioning_date;
                site_updates.site_status = "Provisioning Completed";
                site_updates.lms_stage = "LMS Delivered";
                installation_status = "Provisioning Completed";
                confirmation_message = "Do you want to update the Site and Installation Master as 'Provisioning Completed'?";
            }

            else if (frm.doc.status === 'Partially Completed') {
                site_updates.provisioning_partially_completed_date = frm.doc.provisioning_partially_completed_date;
                site_updates.site_status = "Partially Provisioning Completed";
                site_updates.lms_stage = "LMS Partially Delivered";
                installation_status = "Partially Provisioning Completed";
                confirmation_message = "Do you want to update the Site and Installation Master as 'Partially Provisioning Completed'?";
            }

            frappe.confirm(__(confirmation_message), function() {

                // ✅ Update Site
                frappe.call({
                    method: "frappe.client.set_value",
                    args: {
                        doctype: "Site",
                        name: frm.doc.circuit_id,
                        fieldname: site_updates
                    },
                    callback: function() {
                        frappe.msgprint('✅ Site updated successfully.');
                    }
                });

                // ✅ Update Installation Master
                frappe.call({
                    method: "frappe.client.get_list",
                    args: {
                        doctype: "Installation Master",
                        filters: { provisioning_id: frm.doc.name },
                        fields: ["name"]
                    },
                    callback: function(res) {

                        if (res.message && res.message.length > 0) {

                            let inst_name = res.message[0].name;

                            frappe.call({
                                method: "frappe.client.set_value",
                                args: {
                                    doctype: "Installation Master",
                                    name: inst_name,
                                    fieldname: {
                                        installation_status: installation_status
                                    }
                                },
                                callback: function() {
                                    frappe.msgprint({
                                        title: "Installation Updated",
                                        message: `✅ Installation Master <b>${inst_name}</b> set to <b>${installation_status}</b>.`,
                                        indicator: "green"
                                    });
                                }
                            });

                        } else {
                            frappe.msgprint({
                                title: "No Installation Found",
                                message: `⚠️ No Installation Master found for provisioning_id = ${frm.doc.name}`,
                                indicator: "orange"
                            });
                        }
                    }
                });
            });
        }
    }
});


