frappe.ui.form.on('Installation Master', {
    refresh: function(frm) {
        let button_label = frm.doc.provisioning_id ? "Provisioning Requested" : "Provisioning";

        let btn = frm.add_custom_button(__(button_label), function () {
            // If provisioning already created, do nothing
            if (frm.doc.provisioning_id) {
                frappe.msgprint("Provisioning already created: " + frm.doc.provisioning_id);
                return;
            }

            if (!frm.doc.circuit_id) {
                frappe.msgprint("Please enter a Circuit ID before proceeding.");
                return;
            }

            // Check if Circuit ID is already linked
            frappe.db.get_list("Installation Master", {
                filters: { provisioning_id: ["!=", ""], circuit_id: frm.doc.circuit_id },
                fields: ["name"],
                limit: 1
            }).then(function(existing_links) {
                if (existing_links.length > 0) {
                    frappe.msgprint("This Circuit ID is already linked to another Provisioning record.");
                    return;
                }

                // Create new Provisioning record
                frappe.call({
                    method: "frappe.client.insert",
                    args: {
                        doc: {
                            doctype: "Provisioning",
                            circuit_id: frm.doc.circuit_id
                        }
                    },
                    callback: function(res) {
                        if (res.message) {
                            const provisioning_id = res.message.name;

                            // Update installation master
                            frm.set_value("provisioning_id", provisioning_id);
                            frm.set_value("installation_status", "Provisioning Requested");

                            // Update Site record
                            frappe.db.get_list("Site", {
                                filters: { circuit_id: frm.doc.circuit_id },
                                fields: ["name"],
                                limit: 1
                            }).then(function(site_result) {
                                if (site_result.length > 0) {
                                    const site_name = site_result[0].name;

                                    frappe.call({
                                        method: "frappe.client.set_value",
                                        args: {
                                            doctype: "Site",
                                            name: site_name,
                                            fieldname: "site_status",
                                            value: "Provisioning"
                                        },
                                        callback: function() {
                                            frm.save();
                                            frappe.show_alert({
                                                message: "Provisioning created, Site and Installation updated.",
                                                indicator: "green"
                                            });
                                        }
                                    });
                                } else {
                                    frappe.msgprint("No Site record found with the matching Circuit ID.");
                                    frm.save();
                                }
                            });
                        }
                    }
                });
            });
        });

        // Style based on provisioning_id
        if (frm.doc.provisioning_id) {
            $(btn).css({
                "background-color": "green",
                "color": "white",
                "font-weight": "bold",
                "border": "1px solid green",
                "pointer-events": "none",
                "opacity": "0.8"
            });
        } else {
            $(btn).css({
                "background-color": "red",
                "color": "white",
                "font-weight": "bold",
                "border": "1px solid red"
            });
        }
    }
});

frappe.ui.form.on('HD Ticket', {
