                console.log("Is L1 Support:", r.message);  // Debug log
                if (r.message) {
                    // Method 1: Hide using field property (most reliable)
                    frm.set_df_property('assigned_to', 'hidden', 1);

                    // Method 2: Hide section via DOM (fallback)
                    frm.fields_dict.assigned_to?.$wrapper.closest('.form-section').hide();

                    frm.refresh_fields();
                } else {
                    // Explicitly show for non-L1 users
                    frm.set_df_property('assigned_to', 'hidden', 0);
                    frm.page.wrapper.find(".form-assignments").show();
                }
            },
            error: function(err) {
                console.error("Role check failed - showing field by default", err);
                frm.set_df_property('assigned_to', 'hidden', 0);
            }
        });
    }
});

