function render_lms_table(frm) {
    frappe.db.get_list('Lastmile Services Master', {
        filters: {
            circuit_id: frm.doc.circuit_id,
            lms_stage: 'Delivered'
        },
        fields: [
            'name',
            'lms_feasibility_partner',
            'supplier_contact',
            'solution',
            'lms_stage',
            'lms_delivery_date',
            'suppliernumber',
            'lms_brandwith_name',
            'media',
            'mode1',
            'static_ip',
            'static_ip_1',
            'url',
            'user_id',
            'password'
        ]
    }).then(records => {
        if (!records || records.length === 0) {
            frappe.msgprint(__('LMS records not found for this circuit ID.'));
            frm.fields_dict.custom_lms_html_table.$wrapper.html('');
            frm.set_value('show_lms_information', 0);
            return;
        }

        let html = '';
        let promises = [];

        records.forEach((record, index) => {
