function format_timeline_datetime(wrapper) {
    wrapper.find(".timeline-item .frappe-timestamp").each(function () {
        let $el = $(this);
        let actual_time = $el.attr("data-timestamp");
        if (actual_time) {
            let formatted_time = frappe.datetime.str_to_user(actual_time)
                + " "
                + frappe.datetime.get_time(actual_time);
            $el.text(formatted_time);
        }
    });
}

frappe.ui.form.on("HD Ticket", {
    refresh: function (frm) {
        // Format existing timeline items
        format_timeline_datetime(frm.timeline.wrapper);

        // Observe timeline wrapper for new items
        const targetNode = frm.timeline.wrapper[0];
        if (targetNode && !targetNode._observerAttached) {
            let timeout = null;

            const observer = new MutationObserver(() => {
                // Clear previous timer
                if (timeout) clearTimeout(timeout);

                // Run formatter only after 300ms of no new changes
                timeout = setTimeout(() => {
                    format_timeline_datetime(frm.timeline.wrapper);
                }, 300);
            });

            observer.observe(targetNode, {
                childList: true,
                subtree: true
            });

            targetNode._observerAttached = true; // prevent duplicates
        }
    }
});

