		frm.set_query('contract', () => {
			if (!frm.doc.custom_customer) {
				// Block picking until a customer is chosen
				return { filters: { name: ['=', ''] } };
			}

			return {
				doctype: 'Contract',
				filters: {
					party_name: frm.doc.custom_customer
				}
			};
		});

		// 2) Filter Circuit ID child table
		frm.fields_dict['custom_circuit_id'].grid.get_field('circuit_id').get_query = function () {
			if (!frm.doc.custom_customer && !frm._contract_party_name) {
				return { filters: { name: ['=', ''] } };
			}

			const filters = [
				['Feasibility', 'feasibility_status', 'in', ['Feasible', 'High Commercials']],
				['Feasibility', 'sales_order', 'is', 'not set']
			];

			// Filter by Customer
			const customer_for_filter = frm._contract_party_name || frm.doc.custom_customer;
			if (customer_for_filter) {
				filters.push([
					'Feasibility',
					'customer',
					'=',
					customer_for_filter
				]);
			}

			// NEW: Filter by Order Type
			if (frm.doc.custom_order_type) {
				filters.push([
					'Feasibility',
					'order_type',
					'=',
					frm.doc.custom_order_type
				]);
			}

			return { filters };
		};
	},

	// 3) Customer changed
	async custom_customer(frm) {
		if (frm.doc.contract) {
			try {
				const { message } = await frappe.db.get_value(
					'Contract',
					frm.doc.contract,
					'party_name'
				);

				if (message && message.party_name !== frm.doc.custom_customer) {
					frm.set_value('contract', null);
				}
			} catch (e) {
				console.warn('Contract party_name fetch failed:', e);
				frm.set_value('contract', null);
			}
