});

// Client Script — DocType: Site (VIEW-ONLY segmented progress)
// - Shows `site_status` as read-only (no edits)
// - Renders a segmented progress bar
// - Treats selected statuses as "cancel-like" and shows their exact text on the badge
// - When cancel-like: no green fill, no green dots

frappe.ui.form.on('Site', {
  refresh(frm) {
    // Show the field but make it read-only/disabled in UI
    frm.toggle_display('site_status', true);
    frm.set_df_property('site_status', 'read_only', 1);
    // Also hard-disable the widget controls (covers some edge cases)
    frm.toggle_enable('site_status', false);

    render_status_bar_view_only(frm);
  },
  site_status(frm) {
    render_status_bar_view_only(frm);
  }
});

function render_status_bar_view_only(frm) {
  const fld = frm.get_field('site_stage_progress');
  if (!fld || !fld.$wrapper) return;

  // Flow shown on the bar
  const FLOW = [
    "Pending",
    "In-process",
    "Installation Initiated",
    "Provisioning",
    "Partially Provisioning Completed",
    "Provisioning Completed",
    "Awaiting Customer Approval",
    "Delivered and Live"
  ];

  // Special (not on the bar)
  const STATUS_ON_HOLD   = "On Hold";
  const STATUS_CANCELLED = "Cancelled";

  // Treat any of the following as "Cancelled" (cancel-like)
  const CANCEL_EQUIVALENTS = [
    STATUS_CANCELLED,
    "Site Shifted to new location",
    "Site Upgraded to new Circuit",
    "Site degraded to new Circuit"
  ];

  const current = ((frm.doc.site_status || "") + "").trim();

  // Optional history support: array of rows with .status
  const history = (frm.doc.status_history || [])
    .map(r => ((r && r.status) ? (r.status + "").trim() : ""))
    .filter(Boolean);

  const everOnHold = history.includes(STATUS_ON_HOLD) || current === STATUS_ON_HOLD;

  // Cancel-like detection + reason extraction (prefer current, else last in history)
  const cancelReason = findCancelReason(history, current, CANCEL_EQUIVALENTS); // string or null
  const everCancel = Boolean(cancelReason);

  // Utility: index in FLOW (clamped >=0)
  const idxOf = (s) => Math.max(0, FLOW.indexOf(s));

  // Determine "effective" stage to position the red cancel marker:
  // - If cancel-like: use last FLOW stage before the first cancel-like (from history if possible)
  // - Else: use current stage
  let effectiveStage = current;
  if (everCancel) {
    const lastFlowFromHistory = lastFlowStageBeforeCancelMulti(history, FLOW, CANCEL_EQUIVALENTS);
    if (lastFlowFromHistory) effectiveStage = lastFlowFromHistory;
  }

  const curIdx = idxOf(effectiveStage);
  const pct = Math.round((curIdx / Math.max(1, FLOW.length - 1)) * 100);

  // Provisioning indices
  const pStart = FLOW.indexOf("Provisioning");
  const pMid   = FLOW.indexOf("Partially Provisioning Completed");
  const pEnd   = FLOW.indexOf("Provisioning Completed");

  // Colors
  const GREEN  = "#4caf50";
  const ORANGE = "#ff9800";
  const YELLOW = "#ffeb3b";
  const RED    = "#e53935";
  const TRACK  = "#2a2d33";

  // Provisioning segment color based on the **effective** stage
  let provisioningColor = TRACK;
  if (!everCancel) {
    if (curIdx >= pStart && curIdx < pMid) provisioningColor = ORANGE;
    else if (curIdx >= pMid && curIdx < pEnd) provisioningColor = YELLOW;
    else if (curIdx >= pEnd) provisioningColor = GREEN;
  }

  // Geometry helpers
  const segPct  = (fromIdx, toIdx) => ((toIdx - fromIdx) / (FLOW.length - 1)) * 100;
  const leftPct = (atIdx) => (atIdx / (FLOW.length - 1)) * 100;

  // Build dots (view-only)
  // When cancelled: no green dots at all (even index 0).
  const dotsHtml = FLOW.map((stage, i) => {
    const isActive = everCancel ? (i < 0) : (i <= curIdx); // always false if cancelled
    const activeCls = isActive ? "active" : "";
    // Highlight current dot only when NOT cancelled
    const currentClass = (!everCancel && FLOW[i] === effectiveStage) ? "current" : "";
    const safe = frappe.utils.escape_html(stage);
    return `
      <div class="ssp-dot-wrap ${activeCls} ${currentClass}">
        <div class="ssp-dot" title="${safe}"></div>
      </div>
    `;
  }).join("");

  // Labels: green only when not cancelled
  const labelsHtml = FLOW.map((stage, i) => {
    const safe = frappe.utils.escape_html(stage);
    const isActive = everCancel ? false : (i <= curIdx);
    const activeCls = isActive ? "active" : "";
    return `<div class="ssp-label ${activeCls}" title="${safe}">${safe}</div>`;
  }).join("");

  // Sub-bars (under the main green fill)
  const subbars = [];

  // Provisioning overlay (only if NOT cancelled)
  if (!everCancel && pStart >= 0 && pEnd >= 0) {
    subbars.push(
      `<div class="ssp-subbar" style="left:${leftPct(pStart)}%;width:${segPct(pStart, pEnd)}%;background:${provisioningColor};opacity:0.35;"></div>`
    );
  }

  // Cancel marker: thin red slice at the effective index (if ever cancelled)
  if (everCancel) {
    const cancelLeft = leftPct(curIdx);
    subbars.push(
      `<div class="ssp-cancel-marker" style="left:calc(${cancelLeft}% - 1px);background:${RED};"></div>`
    );
  }

  // Right-side header content
  const badgeHtml = (() => {
    const parts = [];
    if (everOnHold) {
      parts.push(`<span class="ssp-badge hold">${__('On Hold (history)')}</span>`);
    }
    if (everCancel && cancelReason) {
      const safeReason = frappe.utils.escape_html(cancelReason);
      parts.push(`<span class="ssp-badge cancel" title="${safeReason}">${safeReason}</span>`);
    } else {
      parts.push(`<span style="font-size:12px;opacity:.75;">${pct}%</span>`);
    }
    return parts.join("");
  })();

  // Green fill: only when NOT cancelled
  const fillWidthPct = everCancel ? 0 : pct;

  fld.$wrapper.empty().html(`
    <style>
      .ssp-container{margin:8px 2px;}
      .ssp-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;}
      .ssp-title{font-weight:600;}
      .ssp-right{display:flex;gap:8px;align-items:center;}
      .ssp-badge{padding:2px 8px;border-radius:10px;font-size:11px;color:#fff;}
      .ssp-badge.hold{background:${RED};}
      .ssp-badge.cancel{background:${RED};font-weight:600;}

      .ssp-bar{position:relative;height:8px;background:${TRACK};border-radius:6px;overflow:hidden;}
      .ssp-subbar{position:absolute;top:0;height:100%;}
      .ssp-fill{position:absolute;left:0;top:0;height:100%;width:${fillWidthPct}%;background:${GREEN};transition:width .25s ease;border-radius:6px;}

      /* thin vertical cancel marker */
      .ssp-cancel-marker{
        position:absolute;top:-4px;width:2px;height:16px;border-radius:1px;
      }

      .ssp-dots{display:flex;justify-content:space-between;margin-top:-6px;}
      .ssp-dot-wrap{flex:1;text-align:center;cursor:default;}
      .ssp-dot{width:12px;height:12px;border-radius:50%;background:#616b74;border:2px solid #7a8792;margin:0 auto;}
      .ssp-dot-wrap.active .ssp-dot{background:${GREEN};border-color:${GREEN};}
      .ssp-dot-wrap.current .ssp-dot{box-shadow:0 0 0 4px rgba(76,175,80,0.2);}

      .ssp-labels{display:flex;flex-wrap:wrap;justify-content:space-between;margin-top:6px;}
      .ssp-label{flex:1;min-width:110px;max-width:150px;font-size:11px;line-height:1.3;text-align:center;white-space:normal;word-wrap:break-word;margin:0 2px;}
      .ssp-label.active{color:${GREEN};font-weight:500;}
      @media(max-width:900px){.ssp-label{min-width:90px;max-width:120px;font-size:10px;}}
    </style>

    <div class="ssp-container">
      <div class="ssp-header">
        <div class="ssp-title">${__('Site Status')}</div>
        <div class="ssp-right">${badgeHtml}</div>
      </div>

      <div class="ssp-bar">
        ${subbars.join("")}
        <div class="ssp-fill"></div>
      </div>

      <div class="ssp-dots">${dotsHtml}</div>
      <div class="ssp-labels">${labelsHtml}</div>
    </div>
  `);
}

/**
 * Find the last FLOW stage before any cancel-like status in history.
 * If no explicit cancel position found but current is cancel-like, fall back
 * to the latest FLOW status in history.
 */
function lastFlowStageBeforeCancelMulti(history, FLOW, CANCEL_SET) {
  if (!Array.isArray(history) || history.length === 0) return null;

  // Walk from end to start until we hit any cancel-like status;
  // keep the last FLOW item before that.
  let sawCancel = false;
  for (let i = history.length - 1; i >= 0; i--) {
    const s = (history[i] || "").trim();
    if (CANCEL_SET.includes(s)) { sawCancel = true; continue; }
    if (sawCancel && FLOW.includes(s)) return s;
  }

  // Fallback: latest FLOW status in history
  for (let i = history.length - 1; i >= 0; i--) {
    if (FLOW.includes(history[i])) return history[i];
  }
  return null;
}

/**
 * Determine the specific cancel-like reason to display.
 * Priority: current status if cancel-like; otherwise the most recent cancel-like in history.
 */
function findCancelReason(history, current, CANCEL_SET) {
  if (CANCEL_SET.includes(current)) return current;
  if (Array.isArray(history) && history.length) {
    for (let i = history.length - 1; i >= 0; i--) {
      const s = (history[i] || "").trim();
      if (CANCEL_SET.includes(s)) return s;
    }
  }
  return null;
}

// Client Script — DocType: Lastmile Services Master
// Progress bar for LMS Stage (view-only, show green till Delivered; red/grey for disconnection)

frappe.ui.form.on('Lastmile Services Master', {
  refresh(frm) {
    // keep lms_stage visible per requirement
    render_lms_progress(frm);
  },
  lms_stage(frm) {
    render_lms_progress(frm);
  }
});

function render_lms_progress(frm) {
  const htmlFieldname = 'lms_stage_progress';
  const statusFieldname = 'lms_stage';
  const fld = frm.get_field(htmlFieldname);
  if (!fld || !fld.$wrapper) return;

  // Base flow (always shown)
  const BASE_FLOW = [
    "PO Pending",
    "PO Requested",
    "PO Released",
    "In process",
    "Delivered"
  ];
  // Disconnection flow (conditionally added)
  const DISCON_FLOW = ["Disconnection In Process", "Disconnected"];
  const ALL_FLOW = BASE_FLOW.concat(DISCON_FLOW);

  const STATUS_CANCELLED = "Cancelled";

  const current = (frm.doc[statusFieldname] || "").trim();

  // Optional history support (rows with .status or .lms_stage)
  const historyRows = (frm.doc.lms_status_history || frm.doc.status_history || []);
  const history = historyRows.map(r => (r.status || r.lms_stage || "").trim()).filter(Boolean);

  // Determine if we should show the disconnection part at all
  const everDisconIP      = history.includes("Disconnection In Process") || current === "Disconnection In Process";
  const everDisconnected  = history.includes("Disconnected") || current === "Disconnected";
  const showDisconnection = everDisconIP || everDisconnected;

  // Build the VISIBLE flow for this record
  const FLOW = showDisconnection ? ALL_FLOW.slice() : BASE_FLOW.slice();

  // Cancel handling (optional)
  const everCancelled = history.includes(STATUS_CANCELLED) || current === STATUS_CANCELLED;

  // For green fill: if cancelled, stop at last flow stage before cancel; else use current
  let effectiveStage = current;
  if (everCancelled) {
    const lastBeforeCancel = lastFlowStageBeforeCancel(history, ALL_FLOW, STATUS_CANCELLED);
    if (lastBeforeCancel) effectiveStage = lastBeforeCancel;
  }

  // Helpers
  const idxVisible = (s) => Math.max(0, FLOW.indexOf(s));
  const idxAll     = (s) => Math.max(0, ALL_FLOW.indexOf(s));
  const leftPct    = (i, len) => (i / (len - 1)) * 100;
  const segPct     = (a, b, len) => ((b - a) / (len - 1)) * 100;

  // Indices in the VISIBLE flow
  const deliveredIdxV = idxVisible("Delivered");
  const dipIdxV       = FLOW.indexOf("Disconnection In Process");
  const discIdxV      = FLOW.indexOf("Disconnected");

  // Current index in the VISIBLE flow (fallback to the closest known)
  let curIdxV = FLOW.indexOf(effectiveStage);
  if (curIdxV < 0) {
    const fallback = lastSeenFrom(history.concat([current]), FLOW) || FLOW[0];
    curIdxV = idxVisible(fallback);
  }

  // === Fill segments ===
  // 1) Green: up to MIN(current, Delivered)
  const greenEndIdx = Math.min(curIdxV, deliveredIdxV);
  const greenWidth  = Math.max(0, leftPct(greenEndIdx, FLOW.length));
  const greenFill   = `<div class="lms-fill-green" style="width:${greenWidth}%"></div>`;

  // 2) Red: Delivered -> Disconnection In Process (only if disconnection applicable AND reached DIP or beyond)
  let redFill = "";
  if (showDisconnection && dipIdxV >= 0 && curIdxV >= dipIdxV) {
    const left = leftPct(deliveredIdxV, FLOW.length);
    const width = segPct(deliveredIdxV, Math.min(curIdxV, dipIdxV), FLOW.length);
    if (width > 0) redFill = `<div class="lms-fill-red" style="left:${left}%;width:${width}%"></div>`;
  }

  // 3) Grey: Disconnection In Process -> Disconnected (only if reached Disconnected)
  let greyFill = "";
  if (showDisconnection && dipIdxV >= 0 && discIdxV >= 0 && curIdxV >= discIdxV) {
    const left = leftPct(dipIdxV, FLOW.length);
    const width = segPct(dipIdxV, Math.min(curIdxV, discIdxV), FLOW.length);
    if (width > 0) greyFill = `<div class="lms-fill-grey" style="left:${left}%;width:${width}%"></div>`;
  }

  // Cancel marker (thin red line at the last reached flow stage before cancel)
  let cancelMarkerHtml = "";
  if (everCancelled) {
    cancelMarkerHtml = `<div class="lms-cancel-marker" style="left:calc(${leftPct(curIdxV, FLOW.length)}% - 1px);"></div>`;
  }

  // Dots (view-only)
  const dotsHtml = FLOW.map((stage, i) => {
    const active = i <= curIdxV ? "active" : "";
    const currentClass = (FLOW[i] === effectiveStage) ? "current" : "";
    const roleClass =
      (stage === "Disconnection In Process") ? "discon-ip" :
      (stage === "Disconnected") ? "disconnected" : "";
    const safe = frappe.utils.escape_html(stage);
    return `
      <div class="lms-dot-wrap ${active} ${currentClass} ${roleClass}">
        <div class="lms-dot" title="${safe}"></div>
      </div>
    `;
  }).join("");

  // Labels (wrapped — no overlap)
  const labelsHtml = FLOW.map((stage, i) => {
    const safe = frappe.utils.escape_html(stage);
    const active = i <= curIdxV ? "active" : "";
    return `<div class="lms-label ${active}" title="${safe}">${safe}</div>`;
  }).join("");

  // Render
  fld.$wrapper.empty().html(`
    <style>
      .lms-container{margin:8px 2px;}
      .lms-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;}
      .lms-title{font-weight:600;}
      .lms-right{display:flex;gap:8px;align-items:center;}
      .lms-badge{padding:2px 8px;border-radius:10px;font-size:11px;color:#fff;background:#e53935;font-weight:600;}

      .lms-bar{position:relative;height:8px;background:#2a2d33;border-radius:6px;overflow:hidden;}
      .lms-fill-green{position:absolute;left:0;top:0;height:100%;background:#4caf50;transition:width .2s;border-radius:6px;}
      .lms-fill-red{position:absolute;top:0;height:100%;background:#e53935;}
      .lms-fill-grey{position:absolute;top:0;height:100%;background:#9e9e9e;}
      .lms-cancel-marker{position:absolute;top:-4px;width:2px;height:16px;border-radius:1px;background:#e53935;}

      .lms-dots{display:flex;justify-content:space-between;margin-top:-6px;}
      .lms-dot-wrap{flex:1;text-align:center;cursor:default;}
      .lms-dot{width:12px;height:12px;border-radius:50%;background:#616b74;border:2px solid #7a8792;margin:0 auto;}
      /* Color active dots by segment */
      .lms-dot-wrap.active:not(.discon-ip):not(.disconnected) .lms-dot{background:#4caf50;border-color:#4caf50;}
      .lms-dot-wrap.discon-ip.active .lms-dot{background:#e53935;border-color:#e53935;}
      .lms-dot-wrap.disconnected.active .lms-dot{background:#9e9e9e;border-color:#9e9e9e;}
      .lms-dot-wrap.current .lms-dot{box-shadow:0 0 0 4px rgba(76,175,80,0.2);}

      .lms-labels{display:flex;flex-wrap:wrap;justify-content:space-between;margin-top:6px;}
      .lms-label{flex:1;min-width:110px;max-width:150px;font-size:11px;line-height:1.3;text-align:center;white-space:normal;word-wrap:break-word;margin:0 2px;}
      .lms-label.active{color:inherit;font-weight:600;}
      @media(max-width:900px){.lms-label{min-width:90px;max-width:120px;font-size:10px;}}
    </style>

    <div class="lms-container">
      <div class="lms-header">
        <div class="lms-title">${__('LMS Stage')}</div>
        <div class="lms-right">
          ${everCancelled ? `<span class="lms-badge">${__('Cancelled')}</span>` : `<span style="font-size:12px;opacity:.75;">${Math.round((curIdxV/(FLOW.length-1))*100)}%</span>`}
        </div>
      </div>

      <div class="lms-bar">
        ${redFill}
        ${greyFill}
        ${greenFill}
        ${cancelMarkerHtml}
      </div>

      <div class="lms-dots">${dotsHtml}</div>
      <div class="lms-labels">${labelsHtml}</div>
    </div>
  `);
}

/** Last FLOW stage seen before CANCEL in history. */
function lastFlowStageBeforeCancel(history, FLOW, CANCEL) {
  if (!Array.isArray(history) || history.length === 0) return null;
  let sawCancel = false;
  for (let i = history.length - 1; i >= 0; i--) {
    const s = history[i];
    if (s === CANCEL) { sawCancel = true; continue; }
    if (sawCancel && FLOW.includes(s)) return s;
  }
  // fallback: latest FLOW stage seen
  for (let i = history.length - 1; i >= 0; i--) {
    if (FLOW.includes(history[i])) return history[i];
  }
  return null;
}

/** Latest item from arr that belongs to FLOW. */
function lastSeenFrom(arr, FLOW) {
  if (!Array.isArray(arr) || arr.length === 0) return null;
  for (let i = arr.length - 1; i >= 0; i--) {
    if (FLOW.includes(arr[i])) return arr[i];
  }
  return null;
}

// Progress bar for Provisioning.status -> provisioning_stage_progress (HTML)
// - Shows "Pending → Partially Completed → Completed"
// - If the record jumps Pending → Completed (never Partially Completed), the step is hidden
// - "On hold" is not on the bar; shows a red badge; progress stops at last achieved step
// - View-only; keeps the `status` field visible

frappe.ui.form.on('Provisioning', {
  refresh(frm) {
    render_provisioning_progress(frm);
  },
  status(frm) {
    render_provisioning_progress(frm);
  }
});

function render_provisioning_progress(frm) {
  const htmlField = frm.get_field('provisioning_stage_progress');
  if (!htmlField || !htmlField.$wrapper) return;

  // Canonical stage labels (exact text used for display)
  const STAGE_PENDING   = "Pending";
  const STAGE_PARTIAL   = "Partially Completed";
  const STAGE_COMPLETED = "Completed";
  const STAGE_ON_HOLD   = "On hold";

  // Current status (raw)
  const currentRaw = (frm.doc.status || "").trim();

  // Normalize helper (handles "Partial Completed" vs "Partially Completed")
  const norm = s => (s || "").toString().trim().toLowerCase().replace(/\s+/g, " ");
  const isPending   = s => norm(s) === "pending";
  const isPartial   = s => ["partially completed", "partial completed"].includes(norm(s));
  const isCompleted = s => norm(s) === "completed";
  const isOnHold    = s => ["on hold", "on-hold"].includes(norm(s));

  // Optional history: use child table if you have one; else generic status_history
  // Rows should have either .status or a similarly named field.
  const histRows = (frm.doc.provisioning_status_history || frm.doc.status_history || []);
  const hist = histRows
    .map(r => (r.status || r.state || r.stage || "").toString().trim())
    .filter(Boolean);

  const everPartial   = hist.some(isPartial)   || isPartial(currentRaw);
  const everCompleted = hist.some(isCompleted) || isCompleted(currentRaw);
  const everOnHold    = hist.some(isOnHold)    || isOnHold(currentRaw);

  // Decide the visible flow:
  // - If the record never touched "Partially Completed", hide that middle step.
  const FLOW = everPartial
    ? [STAGE_PENDING, STAGE_PARTIAL, STAGE_COMPLETED]
    : [STAGE_PENDING, STAGE_COMPLETED];

  // Find the "last achieved" stage to compute green fill
  function lastAchievedStage() {
    // If current is one of the visible FLOW stages, use it directly
    if (FLOW.includes(currentRaw)) return currentRaw;

    // If current is Completed but FLOW is [Pending, Completed]
    if (isCompleted(currentRaw)) return STAGE_COMPLETED;

    // If current is On hold, find the latest stage in history that belongs to current FLOW
    if (isOnHold(currentRaw)) {
      for (let i = hist.length - 1; i >= 0; i--) {
        const s = hist[i];
        if (FLOW.includes(s)) return s;
        if (isCompleted(s)) return STAGE_COMPLETED;
        if (isPartial(s) && FLOW.includes(STAGE_PARTIAL)) return STAGE_PARTIAL;
        if (isPending(s)) return STAGE_PENDING;
      }
      return STAGE_PENDING;
    }

    // Fallbacks based on history/current
    if (everCompleted) return STAGE_COMPLETED;
    if (everPartial && FLOW.includes(STAGE_PARTIAL)) return STAGE_PARTIAL;
    if (isPending(currentRaw)) return STAGE_PENDING;

    // Default
    return STAGE_PENDING;
  }

  const achieved = lastAchievedStage();
  const curIdx   = Math.max(0, FLOW.indexOf(achieved));
  const pct      = Math.round((curIdx / Math.max(1, FLOW.length - 1)) * 100);

  // Geometry helpers
  const leftPct = (idx, len) => (idx / (len - 1)) * 100;

  // Build dots (view-only)
  const dotsHtml = FLOW.map((stage, i) => {
    const active = i <= curIdx ? "active" : "";
    const currentClass = (stage === achieved) ? "current" : "";
    const safe = frappe.utils.escape_html(stage);
    return `
      <div class="prov-dot-wrap ${active} ${currentClass}">
        <div class="prov-dot" title="${safe}"></div>
      </div>
    `;
  }).join("");

  // Labels (wrapped; no fading)
  const labelsHtml = FLOW.map((stage, i) => {
    const safe = frappe.utils.escape_html(stage);
    const active = i <= curIdx ? "active" : "";
    return `<div class="prov-label ${active}" title="${safe}">${safe}</div>`;
  }).join("");

  // Render
  htmlField.$wrapper.empty().html(`
    <style>
      .prov-container{margin:8px 2px;}
      .prov-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;}
      .prov-title{font-weight:600;}
      .prov-right{display:flex;gap:8px;align-items:center;}
      .prov-badge{padding:2px 8px;border-radius:10px;font-size:11px;color:#fff;background:#e53935;font-weight:600;}

      .prov-bar{position:relative;height:8px;background:#2a2d33;border-radius:6px;overflow:hidden;}
      .prov-fill{position:absolute;left:0;top:0;height:100%;width:${pct}%;background:#4caf50;transition:width .2s;border-radius:6px;}

      .prov-dots{display:flex;justify-content:space-between;margin-top:-6px;}
      .prov-dot-wrap{flex:1;text-align:center;cursor:default;}
      .prov-dot{width:12px;height:12px;border-radius:50%;background:#616b74;border:2px solid #7a8792;margin:0 auto;}
      .prov-dot-wrap.active .prov-dot{background:#4caf50;border-color:#4caf50;}
      .prov-dot-wrap.current .prov-dot{box-shadow:0 0 0 4px rgba(76,175,80,0.2);}

      .prov-labels{display:flex;flex-wrap:wrap;justify-content:space-between;margin-top:6px;}
      .prov-label{flex:1;min-width:110px;max-width:160px;font-size:11px;line-height:1.3;text-align:center;white-space:normal;word-wrap:break-word;margin:0 2px;}
      .prov-label.active{color:inherit;font-weight:600;} /* no fading */
      @media(max-width:900px){.prov-label{min-width:90px;max-width:120px;font-size:10px;}}
    </style>

    <div class="prov-container">
      <div class="prov-header">
        <div class="prov-title">${__('Provisioning Status')}</div>
        <div class="prov-right">
          ${ (everOnHold ? `<span class="prov-badge">${__('On hold')}</span>` : `<span style="font-size:12px;opacity:.75;">${pct}%</span>`) }
        </div>
      </div>

      <div class="prov-bar">
        <div class="prov-fill"></div>
      </div>

      <div class="prov-dots">${dotsHtml}</div>
      <div class="prov-labels">${labelsHtml}</div>
    </div>
  `);
}

// Client Script — DocType: Opportunity
// View-only sales pipeline for `sales_stage` into HTML field `custom_deal_stage`

frappe.ui.form.on('Opportunity', {
  refresh(frm) {
    render_deal_stage_bar(frm);
  },
  sales_stage(frm) {
    render_deal_stage_bar(frm);
  }
});

function render_deal_stage_bar(frm) {
  const fld = frm.get_field('custom_deal_stage');
  if (!fld || !fld.$wrapper) return;

  // ---- Canonical stage names (logic uses these, regardless of numeric prefixes in options)
  const FLOW = [
    "Qualification",
    "Prospecting",
    "Needs Analysis",
    "Identifying Decision Makers",
    "Value Proposition",
    "Proposal/Price Quote",
    "Perception Analysis",
    "Negotiation/Review"
  ];
  const CLOSE_WON   = "Close Won";
  const CLOSED_LOST = "Closed Lost to Competition";
  const CLOSED_DROP = "Closed Drop";

  // Normalize input: remove leading numbers "1. ", punctuation, arrows, collapse spaces, lowercase
  const canon = s => (s || "")
    .toString()
    .replace(/^\s*\d+\s*[.)-]?\s*/i, "")   // strip "1. " or "1) " etc
    .replace(/→/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();

  const isWon   = s => ["close won","closed won","won"].includes(canon(s));
  const isLost  = s => ["closed lost to competition","lost to competition","lost"].includes(canon(s));
  const isDrop  = s => ["closed drop","drop","dropped","closed dropped"].includes(canon(s));
  const closeLabel = s => (isWon(s) ? CLOSE_WON : isLost(s) ? CLOSED_LOST : isDrop(s) ? CLOSED_DROP : null);

  const raw = (frm.doc.sales_stage || "").trim();
  const currentClose = closeLabel(raw); // null when not closed

  // Build the labels we show (display text). If not closed, show "Closing" as last label.
  const DISPLAY = FLOW.slice();  // first 8 labels
  DISPLAY.push(currentClose ? currentClose : "Closing");

  // Which index are we at?
  const idxInFlow = (stage) => FLOW.indexOf(stage);
  const idxInDisplay = (label) => DISPLAY.indexOf(label);

  // Try to map the current raw value to a canonical stage or closing outcome
  let curIdx;
  if (currentClose) {
    curIdx = DISPLAY.length - 1; // closed → last node
  } else {
    // map raw to one of FLOW items
    const rawCanon = canon(raw);
    const found = FLOW.find(s => canon(s) === rawCanon);
    curIdx = found ? idxInDisplay(found) : 0;
  }

  // % completion
  const pct = Math.round((curIdx / Math.max(1, DISPLAY.length - 1)) * 100);

  // Colors
  const GREEN = "#4caf50";
  const RED   = "#e53935";
  const GRAY  = "#9e9e9e";
  const TRACK = "#2a2d33";

  // Geometry helpers
  const leftPct  = (i, len) => (i / (len - 1)) * 100;
  const segPct   = (a, b, len) => ((b - a) / (len - 1)) * 100;

  // Build fills:
  // 1) Green up to (but not including) last segment unless it's Close Won
  const lastIdx = DISPLAY.length - 1;
  const negotiationIdx = idxInDisplay("Negotiation/Review"); // always index 7
  const greenEndIdx = currentClose
    ? (isWon(raw) ? lastIdx : Math.min(curIdx, negotiationIdx))  // if won → go all green; else stop at negotiation
    : curIdx;

  const greenWidth = Math.max(0, leftPct(greenEndIdx, DISPLAY.length));
  const greenFill = `<div class="opp-fill-green" style="width:${greenWidth}%"></div>`;

  // 2) Closing segment overlay (Negotiation → Last)
  let closeOverlay = "";
  if (curIdx >= negotiationIdx && currentClose) {
    const left = leftPct(negotiationIdx, DISPLAY.length);
    const width = segPct(negotiationIdx, lastIdx, DISPLAY.length);
    const color = isWon(raw) ? GREEN : isLost(raw) ? RED : GRAY;
    closeOverlay = `<div class="opp-fill-close" style="left:${left}%;width:${width}%;background:${color};"></div>`;
  }

  // Dots (view-only)
  const dotsHtml = DISPLAY.map((label, i) => {
    const active = i <= curIdx ? "active" : "";
    const currentClass = (i === curIdx) ? "current" : "";
    const roleClass =
      (i === lastIdx && currentClose && isLost(raw)) ? "lost" :
      (i === lastIdx && currentClose && isDrop(raw)) ? "drop" :
      (i === lastIdx && currentClose && isWon(raw))  ? "won"  : "";
    const safe = frappe.utils.escape_html(label);
    return `
      <div class="opp-dot-wrap ${active} ${currentClass} ${roleClass}">
        <div class="opp-dot" title="${safe}"></div>
      </div>
    `;
  }).join("");

  // Labels (wrapped; no fading)
  const labelsHtml = DISPLAY.map((label, i) => {
    const safe = frappe.utils.escape_html(label);
    const active = i <= curIdx ? "active" : "";
    return `<div class="opp-label ${active}" title="${safe}">${safe}</div>`;
  }).join("");

  // Render
  fld.$wrapper.empty().html(`
    <style>
      .opp-container{margin:8px 2px;}
      .opp-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;}
      .opp-title{font-weight:600;}
      .opp-right{font-size:12px;opacity:.75;}

      .opp-bar{position:relative;height:8px;background:${TRACK};border-radius:6px;overflow:hidden;}
      .opp-fill-green{position:absolute;left:0;top:0;height:100%;background:${GREEN};transition:width .2s;border-radius:6px;}
      .opp-fill-close{position:absolute;top:0;height:100%;}

      .opp-dots{display:flex;justify-content:space-between;margin-top:-6px;}
      .opp-dot-wrap{flex:1;text-align:center;cursor:default;}
      .opp-dot{width:12px;height:12px;border-radius:50%;background:#616b74;border:2px solid #7a8792;margin:0 auto;}
      .opp-dot-wrap.active .opp-dot{background:${GREEN};border-color:${GREEN};}
      .opp-dot-wrap.won.active .opp-dot{background:${GREEN};border-color:${GREEN};}
      .opp-dot-wrap.lost.active .opp-dot{background:${RED};border-color:${RED};}
      .opp-dot-wrap.drop.active .opp-dot{background:${GRAY};border-color:${GRAY};}
      .opp-dot-wrap.current .opp-dot{box-shadow:0 0 0 4px rgba(76,175,80,0.2);}

      .opp-labels{display:flex;flex-wrap:wrap;justify-content:space-between;margin-top:6px;}
      .opp-label{flex:1;min-width:110px;max-width:170px;font-size:11px;line-height:1.3;text-align:center;white-space:normal;word-wrap:break-word;margin:0 2px;}
      .opp-label.active{color:inherit;font-weight:600;}
      @media(max-width:1000px){.opp-label{min-width:95px;max-width:135px;font-size:10px;}}
    </style>

    <div class="opp-container">
      <div class="opp-header">
        <div class="opp-title">${__('Deal Stage')}</div>
        <div class="opp-right">${pct}%</div>
      </div>

      <div class="opp-bar">
        ${closeOverlay}
        ${greenFill}
      </div>

      <div class="opp-dots">${dotsHtml}</div>
      <div class="opp-labels">${labelsHtml}</div>
    </div>
  `);
}

// Progress bar for Lead.qualification_status -> custom_lead_qualification (HTML)
// Stages: Unqualified → In Process → Qualified
// View-only; keeps the Select field visible.

frappe.ui.form.on('Lead', {
  refresh(frm) {
    render_lead_qualification_bar(frm);
  },
  qualification_status(frm) {
    render_lead_qualification_bar(frm);
  }
});

function render_lead_qualification_bar(frm) {
  const htmlField = frm.get_field('custom_lead_qualification');
  if (!htmlField || !htmlField.$wrapper) return;

  const FLOW = ["Unqualified", "In Process", "Qualified"];
  const current = (frm.doc.qualification_status || "").trim();

  // Index of current stage (clamp to 0 if unknown)
  const curIdx = Math.max(0, FLOW.indexOf(current));
  const pct = Math.round((curIdx / Math.max(1, FLOW.length - 1)) * 100);

  // Helpers
  const leftPct = (idx, len) => (idx / (len - 1)) * 100;

  // Dots (view-only)
  const dotsHtml = FLOW.map((stage, i) => {
    const active = i <= curIdx ? "active" : "";
    const currentClass = (FLOW[i] === current) ? "current" : "";
    const safe = frappe.utils.escape_html(stage);
    return `
      <div class="lead-dot-wrap ${active} ${currentClass}">
        <div class="lead-dot" title="${safe}"></div>
      </div>
    `;
  }).join("");

  // Labels (wrapped; no fading)
  const labelsHtml = FLOW.map((stage, i) => {
    const safe = frappe.utils.escape_html(stage);
    const active = i <= curIdx ? "active" : "";
    return `<div class="lead-label ${active}" title="${safe}">${safe}</div>`;
  }).join("");

  // Render
  htmlField.$wrapper.empty().html(`
    <style>
      .lead-container{margin:8px 2px;}
      .lead-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;}
      .lead-title{font-weight:600;}
      .lead-right{font-size:12px;opacity:.75;}

      .lead-bar{position:relative;height:8px;background:#2a2d33;border-radius:6px;overflow:hidden;}
      .lead-fill{position:absolute;left:0;top:0;height:100%;width:${pct}%;background:#4caf50;transition:width .2s;border-radius:6px;}

      .lead-dots{display:flex;justify-content:space-between;margin-top:-6px;}
      .lead-dot-wrap{flex:1;text-align:center;cursor:default;}
      .lead-dot{width:12px;height:12px;border-radius:50%;background:#616b74;border:2px solid #7a8792;margin:0 auto;}
      .lead-dot-wrap.active .lead-dot{background:#4caf50;border-color:#4caf50;}
      .lead-dot-wrap.current .lead-dot{box-shadow:0 0 0 4px rgba(76,175,80,0.2);}

      .lead-labels{display:flex;flex-wrap:wrap;justify-content:space-between;margin-top:6px;}
      .lead-label{flex:1;min-width:110px;max-width:150px;font-size:11px;line-height:1.3;text-align:center;white-space:normal;word-wrap:break-word;margin:0 2px;}
      .lead-label.active{color:inherit;font-weight:600;} /* no fading */
      @media(max-width:900px){.lead-label{min-width:90px;max-width:120px;font-size:10px;}}
    </style>

    <div class="lead-container">
      <div class="lead-header">
        <div class="lead-title">${__('Lead Qualification')}</div>
        <div class="lead-right">${pct}%</div>
      </div>

      <div class="lead-bar">
        <div class="lead-fill"></div>
      </div>

      <div class="lead-dots">${dotsHtml}</div>
      <div class="lead-labels">${labelsHtml}</div>
    </div>
  `);
}

// Task status progress -> HTML field `custom_task_status_progress`
// Supports visualizing: Rejected -> Resubmitted -> Completed

frappe.ui.form.on('Task', {
  refresh(frm) {
    render_task_status_progress(frm);
  },
  status(frm) {
    render_task_status_progress(frm);
  }
});

function render_task_status_progress(frm) {
  const fld = frm.get_field('custom_task_status_progress');
  if (!fld || !fld.$wrapper) return;

  // Flow on the bar
  const FLOW = ["Open", "Working", "Pending Review"];

  // Terminal outcomes (displayed as the last label)
  const TERM_COMPLETED = "Completed";
  const TERM_REJECTED  = "Rejected";
  const TERM_CANCELLED = "Cancelled";

  // Specials (not on the bar)
  const SPECIAL_OVERDUE  = "Overdue";
  const SPECIAL_TEMPLATE = "Template";

  const raw = (frm.doc.status || "").trim();

  // Helpers / normalizers
  const canon = s => (s || "").toLowerCase().trim();
  const isOpen       = s => canon(s) === "open";
  const isWorking    = s => canon(s) === "working";
  const isReview     = s => canon(s) === "pending review";
  const isCompleted  = s => canon(s) === "completed";
  const isRejected   = s => canon(s) === "rejected";
  const isCancelled  = s => canon(s) === "cancelled";
  const isOverdue    = s => canon(s) === "overdue";
  const isTemplate   = s => canon(s) === "template";
  const inFlow       = s => isOpen(s) || isWorking(s) || isReview(s);

  // Optional history (rows with .status)
  const histRows = (frm.doc.task_status_history || frm.doc.status_history || []);
  const history = histRows.map(r => (r.status || r.state || "").toString().trim()).filter(Boolean);

  // Convenience
  const ever = pred => history.some(pred) || pred(raw);

  // Detect "Rejected → Resubmitted → Completed"
  const rejectedThenResubmittedThenCompleted = (() => {
    const H = history.map(canon);
    const idxRejected   = H.findIndex(v => v === "rejected");
    const idxCompleted  = H.findIndex(v => v === "completed");
    if (idxRejected === -1) return false;

    // Was there any in-flow stage AFTER the rejection?
    const hasResubmissionAfterReject = H.slice(idxRejected + 1).some(v => v === "open" || v === "working" || v === "pending review");

    // Was it completed afterwards (in history or current)?
    const completedAfterReject = (idxCompleted > idxRejected) || (isCompleted(raw) && idxRejected !== -1);

    return hasResubmissionAfterReject && completedAfterReject;
  })();

  const currentIsTerminal = isCompleted(raw) || isRejected(raw) || isCancelled(raw);
  const currentIsSpecial  = isOverdue(raw) || isTemplate(raw);

  // Last label decided by current terminal; if completed, show Completed
  let lastLabel =
    isRejected(raw)  ? TERM_REJECTED  :
    isCancelled(raw) ? TERM_CANCELLED :
    TERM_COMPLETED;

  const DISPLAY = FLOW.concat([lastLabel]);

  // Find "last achieved" in-progress step (for green base fill)
  function lastAchieved() {
    if (currentIsTerminal) {
      // Try the latest flow step in history
      for (let i = history.length - 1; i >= 0; i--) {
        const s = history[i];
        if (inFlow(s)) return normaliseToFlow(s);
      }
      // Default to 'Pending Review' as the final flow step
      return "Pending Review";
    }
    if (isOverdue(raw)) {
      // stick to the latest flow step seen (history or current)
      for (let i = history.length - 1; i >= 0; i--) {
        const s = history[i];
        if (inFlow(s)) return normaliseToFlow(s);
      }
      if (inFlow(raw)) return normaliseToFlow(raw);
      return "Open";
    }
    if (isTemplate(raw)) return "Open";
    if (inFlow(raw)) return normaliseToFlow(raw);
    if (isCompleted(raw)) return "Pending Review";
    return "Open";
  }

  function normaliseToFlow(s) {
    if (isReview(s))  return "Pending Review";
    if (isWorking(s)) return "Working";
    return "Open";
  }

  // Indices / geometry
  const idx = (label, list) => Math.max(0, list.indexOf(label));
  const leftPct = (i, len) => (i / (len - 1)) * 100;
  const segPct  = (a, b, len) => ((b - a) / (len - 1)) * 100;

  const achieved = lastAchieved();
  const achievedIdx = idx(achieved, DISPLAY);
  const reviewIdx   = idx("Pending Review", DISPLAY);
  const lastIdx     = DISPLAY.length - 1;

  // Current marker index
  let curIdx;
  if (currentIsTerminal) curIdx = lastIdx;
  else if (currentIsSpecial) curIdx = achievedIdx;
  else curIdx = idx((inFlow(raw) ? normaliseToFlow(raw) : achieved), DISPLAY);

  // Base green fill: start -> min(achieved, last flow step)
  const baseGreenEndIdx = Math.min(achievedIdx, reviewIdx);
  const baseGreenWidth  = Math.max(0, leftPct(baseGreenEndIdx, DISPLAY.length));
  const baseGreenFill   = `<div class="task-fill-green" style="width:${baseGreenWidth}%"></div>`;

  // Terminal overlay segment (Pending Review -> Last)
  let terminalOverlay = "";
  if (currentIsTerminal) {
    const color = isCompleted(raw) ? "#4caf50" : "#e53935"; // green for Completed, red for Rejected/Cancelled
    const left  = leftPct(reviewIdx, DISPLAY.length);
    const width = segPct(reviewIdx, lastIdx, DISPLAY.length);
    terminalOverlay = `<div class="task-fill-terminal" style="left:${left}%;width:${width}%;background:${color};"></div>`;
  }

  // Rejection HISTORY stripe (thin red band on top of the terminal segment) when Completed after a prior reject
  let rejectHistoryStripe = "";
  if (isCompleted(raw) && rejectedThenResubmittedThenCompleted) {
    const left  = leftPct(reviewIdx, DISPLAY.length);
    const width = segPct(reviewIdx, lastIdx, DISPLAY.length);
    rejectHistoryStripe = `<div class="task-reject-history" title="${frappe.utils.escape_html(__('Rejected earlier, then resubmitted'))}" style="left:${left}%;width:${width}%"></div>`;
  }

  // Badges
  const badges = [];
  if (rejectedThenResubmittedThenCompleted) badges.push(`<span class="task-badge resub">${__('Resubmitted')}</span>`);
  if (ever(isOverdue) && !currentIsTerminal)  badges.push(`<span class="task-badge overdue">${__('Overdue')}</span>`);
  if (ever(isTemplate) && !currentIsTerminal) badges.push(`<span class="task-badge template">${__('Template')}</span>`);

  // Dots (view-only)
  const dotsHtml = DISPLAY.map((label, i) => {
    const active = i <= curIdx ? "active" : "";
    const currentClass = (i === curIdx) ? "current" : "";
    const roleClass =
      (i === lastIdx && isCompleted(raw)) ? "done" :
      (i === lastIdx && (isRejected(raw) || isCancelled(raw))) ? "fail" : "";
    const safe = frappe.utils.escape_html(label);
    return `
      <div class="task-dot-wrap ${active} ${currentClass} ${roleClass}">
        <div class="task-dot" title="${safe}"></div>
      </div>
    `;
  }).join("");

  // Labels
  const labelsHtml = DISPLAY.map((label, i) => {
    const safe = frappe.utils.escape_html(label);
    const active = i <= curIdx ? "active" : "";
    return `<div class="task-label ${active}" title="${safe}">${safe}</div>`;
  }).join("");

  const pct = Math.round((curIdx / Math.max(1, DISPLAY.length - 1)) * 100);

  // Render
  fld.$wrapper.empty().html(`
    <style>
      .task-container{margin:8px 2px;}
      .task-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;}
      .task-title{font-weight:600;}
      .task-right{display:flex;gap:6px;align-items:center;font-size:12px;}

      .task-badge{padding:2px 8px;border-radius:10px;color:#fff;font-weight:600;font-size:11px;}
      .task-badge.overdue{background:#ff9800;}
      .task-badge.template{background:#9e9e9e;}
      .task-badge.resub{background:#4caf50;}

      .task-bar{position:relative;height:10px;background:#2a2d33;border-radius:6px;overflow:hidden;}

      /* base green progress */
      .task-fill-green{position:absolute;left:0;top:0;height:100%;background:#4caf50;transition:width .2s;border-radius:6px;}

      /* terminal overlay (full-height) */
      .task-fill-terminal{position:absolute;top:0;height:100%;}

      /* thin red stripe to indicate a prior rejection during this terminal span */
      .task-reject-history{
        position:absolute;top:0;height:3px;background:#e53935;opacity:0.9;border-top-left-radius:6px;border-top-right-radius:6px;
      }

      .task-dots{display:flex;justify-content:space-between;margin-top:-6px;}
      .task-dot-wrap{flex:1;text-align:center;cursor:default;}
      .task-dot{width:12px;height:12px;border-radius:50%;background:#616b74;border:2px solid #7a8792;margin:0 auto;}
      .task-dot-wrap.active .task-dot{background:#4caf50;border-color:#4caf50;}
      .task-dot-wrap.done.active .task-dot{background:#4caf50;border-color:#4caf50;}
      .task-dot-wrap.fail.active .task-dot{background:#e53935;border-color:#e53935;}
      .task-dot-wrap.current .task-dot{box-shadow:0 0 0 4px rgba(76,175,80,0.2);}

      .task-labels{display:flex;flex-wrap:wrap;justify-content:space-between;margin-top:6px;}
      .task-label{flex:1;min-width:110px;max-width:160px;font-size:11px;line-height:1.3;text-align:center;white-space:normal;word-wrap:break-word;margin:0 2px;}
      .task-label.active{color:inherit;font-weight:600;}
      @media(max-width:950px){.task-label{min-width:95px;max-width:130px;font-size:10px;}}
    </style>

    <div class="task-container">
      <div class="task-header">
        <div class="task-title">${__('Task Status')}</div>
        <div class="task-right">
          ${badges.join('')}
          <span style="opacity:.75;">${pct}%</span>
        </div>
      </div>

      <div class="task-bar">
        ${terminalOverlay}
        ${rejectHistoryStripe}
        ${baseGreenFill}
      </div>

      <div class="task-dots">${dotsHtml}</div>
      <div class="task-labels">${labelsHtml}</div>
    </div>
  `);
}

