frappe.ui.form.on('Site', {
    refresh: function (frm) {
        // Store the initial value of lms_stage for later reversion
        if (!frm.doc.__last_lms_stage) {
            frm.doc.__last_lms_stage = frm.doc.lms_stage;
        }
    },

    lms_type: function (frm) {
        // When user changes LMS Type
        if (frm.doc.lms_type === "No LMS") {
            // Save current stage before overwriting
            frm.doc.__last_lms_stage = frm.doc.lms_stage;

            // Set LMS Stage to No LMS
            frm.set_value("lms_stage", "No LMS");
            frappe.msgprint("LMS Stage has been set to <b>No LMS</b>.");

        } else {
            // Revert to previous stage if it existed and is different
            if (frm.doc.__last_lms_stage && frm.doc.lms_stage === "No LMS") {
                frm.set_value("lms_stage", frm.doc.__last_lms_stage);
                frappe.msgprint("LMS Stage reverted to previous value: <b>" + frm.doc.__last_lms_stage + "</b>");
            }
        }
    }
});

