// Client Script for DocType: ERP Tracker
// Fields expected: status (Select), open_date (Date), consider_date (Date), closed_date (Date)

frappe.ui.form.on('ERP Tracker', {
  onload(frm) {
    // Set open_date on brand new docs (before first save)
    if (frm.is_new() && !frm.doc.open_date) {
      frm.set_value('open_date', frappe.datetime.get_today());
    }
  },

  // Fire whenever status is changed by the user
  status(frm) {
    const s = (frm.doc.status || '').toLowerCase();
    const today = frappe.datetime.get_today();

    if (s === 'consider') {
      // Stamp consider_date only the first time it’s moved to Consider
      if (!frm.doc.consider_date) {
        frm.set_value('consider_date', today);
      }
      // Not completed anymore → ensure closed_date is empty
      if (frm.doc.closed_date) {
        frm.set_value('closed_date', null);
      }
    } else if (s === 'completed') {
      // When completed, stamp closed_date (always refresh to “now” on move to Completed)
      frm.set_value('closed_date', today);

      // If somehow consider_date was never set, you can auto-fill it (optional)
      // Remove this block if you do NOT want this behavior.
      if (!frm.doc.consider_date) {
        frm.set_value('consider_date', today);
      }
    } else {
      // Any other status → closed_date should be None
      if (frm.doc.closed_date) {
        frm.set_value('closed_date', null);
      }
    }
  },

  // Extra safety: after the first save, align open_date to the doc's creation date if still empty
  after_save(frm) {
    if (!frm.doc.open_date && frm.doc.creation) {
      // Use today's date if creation parsing is not desired; creation is a datetime string
      frm.set_value('open_date', frappe.datetime.get_today());
    }
  },
});

frappe.ui.form.on('Purchase Order', {
    refresh(frm) {
        // if supplier already set → skip
        if (frm.doc.supplier) return;

        // find MR number from first PO item
        let mr = null;

        frm.doc.items?.forEach(item => {
            if (item.material_request) {
                mr = item.material_request;
            }
        });

        if (!mr) return;

        frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "Material Request",
                name: mr
            },
            callback(r) {
                if (r.message?.custom_supplier) {
                    frm.set_value("supplier", r.message.custom_supplier);
                }
            }
        });
    }
});

frappe.ui.form.on("Sales Invoice", {
    onload(frm) {

        // Must have items
        if (!frm.doc.items || frm.doc.items.length === 0) return;

        // Run only in Draft
        if (frm.doc.docstatus !== 0) return;

        // Get Sales Order from first item
        const so = frm.doc.items[0].sales_order;
        if (!so) return;

        frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "Sales Order",
                name: so
            },
            callback(r) {

                if (!r.message) return;

                const so_doc = r.message;

                // Set header fields only if empty
                if (!frm.doc.custom_invoice_mode) {
                    frm.set_value("custom_invoice_mode", so_doc.custom_billing_terms);
                }

                if (!frm.doc.custom_order_type) {
                    frm.set_value("custom_order_type", so_doc.order_type);
                }

                // Loop through invoice items
                frm.doc.items.forEach(inv_item => {

                    const so_item = so_doc.items.find(i => i.name === inv_item.so_detail);

                    if (so_item) {

                        // Update circuit id only
                        if (!inv_item.custom_circuit_id) {
                            frappe.model.set_value(
                                inv_item.doctype,
                                inv_item.name,
                                "custom_circuit_id",
                                so_item.custom_feasibility
                            );
                        }
                    }

                });

                frm.refresh_field("items");

            }
        });

    }
});

frappe.ui.form.on("Quotation", {
  refresh(frm) {
    bind_item_code_query_once(frm);
  },

  // This event fires when the grid is rendered (important for child tables)
  items_on_form_rendered(frm) {
    bind_item_code_query_once(frm);
  },

  order_type(frm) {
    // Just refresh the grid; query reads latest order_type automatically
    frm.refresh_field("items");
  }
});

function bind_item_code_query_once(frm) {
  const grid = frm.fields_dict.items?.grid;
  if (!grid) return;

  // Avoid rebinding repeatedly
  if (grid.__item_code_query_bound) return;
  grid.__item_code_query_bound = true;

  grid.get_field("item_code").get_query = function () {
    const ot = (frm.doc.order_type || "").trim();

    let allowed_segments = [];
    if (ot === "Supply") {
      allowed_segments = ["Product"];
    } else if (["Service", "Upgrade", "Degrade", "Shifting"].includes(ot)) {
      allowed_segments = ["Quote", "LMS Bandwidth", "Solution"];
    } else {
      // If you want to show NOTHING until order_type selected, make this []
      allowed_segments = [];
    }

    return {
      // Use ERPNext's item query (same one used in buying/selling forms)
      query: "erpnext.controllers.queries.item_query",
      filters: {
        disabled: 0,
        custom_item_segment: ["in", allowed_segments]
      }
    };
  };
}

