frappe.ui.form.on("Site", {

    onload(frm) {

        let is_admin =
            frappe.session.user === "Administrator" ||
            frappe.user.has_role("System Manager");

        // If date already locked, make it readonly
        if (frm.doc.date_locked && !is_admin) {
            frm.set_df_property("date", "read_only", 1);
        }

    },


    date(frm) {

        if (!frm.doc.date) return;

        let is_admin =
            frappe.session.user === "Administrator" ||
            frappe.user.has_role("System Manager");

        // Order types where backdate is allowed
        let special_orders = ["Upgrade", "Degrade", "Shifting"];

        // If already edited once, stop user
        if (frm.doc.date_locked && !is_admin) {

            frappe.msgprint({
                title: "Not Allowed",
                indicator: "red",
                message: "Date can be edited only once. Please contact Admin."
            });

            frm.reload_doc();
            return;
        }

        // Skip backdate validation for special order types
        if (!special_orders.includes(frm.doc.order_type)) {

            let today = frappe.datetime.get_today();
            let diff = frappe.datetime.get_day_diff(today, frm.doc.date);

            if (diff > 7 && !is_admin) {

                frappe.msgprint({
                    title: "Backdate Not Allowed",
                    indicator: "red",
                    message: "Backdating the Circuit Delivery Date beyond 7 days is not permitted."
                });

                frm.set_value("date", "");
            }
        }

    },


    after_save(frm) {

        let is_admin =
            frappe.session.user === "Administrator" ||
            frappe.user.has_role("System Manager");

        // Lock after first save (for all order types except admin)
        if (!is_admin && !frm.doc.date_locked && frm.doc.date) {

            frappe.db.set_value(
                "Site",
                frm.doc.name,
                "date_locked",
                1
            );

            frm.set_df_property("date", "read_only", 1);
        }

    }

});

frappe.ui.form.on("HD Ticket", {

    refresh(frm) {
        render_eta_history(frm);
    },

    validate(frm) {

        if (!frm.doc.custom_eta) return;

        let history = frm.doc.custom_eta_history || "";

        // Convert ETA to database format
        let current_eta = frappe.datetime.obj_to_str(
            frappe.datetime.str_to_obj(frm.doc.custom_eta)
        );

        // Extract last stored ETA from history
        let last_eta = null;
        let match = history.match(/data-eta="([^"]+)"/);

        if (match) {
            last_eta = match[1];
        }

        // Stop if ETA did not change
        if (last_eta && last_eta === current_eta) {
            return;
        }

        let new_eta = frappe.datetime.str_to_user(frm.doc.custom_eta);
        let now = frappe.datetime.str_to_user(frappe.datetime.now_datetime());
        let user = frappe.session.user;

        let entry = `
        <div class="eta-entry" data-eta="${current_eta}">
            <b>ETA Updated</b><br>
            ${new_eta}<br>
            <span class="eta-meta">${user} • ${now}</span>
        </div>
        `;

        frm.doc.custom_eta_history = entry + history;
    }

});


function render_eta_history(frm){

    if (!frm.fields_dict.custom_eta_tracker) return;

    let history = frm.doc.custom_eta_history;

    if (!history){
        frm.fields_dict.custom_eta_tracker.$wrapper.html("");
        return;
    }

    let temp = document.createElement("div");
    temp.innerHTML = history;

    let entries = temp.querySelectorAll(".eta-entry");

    let visible_entries = [];

    for(let i=0;i<Math.min(entries.length,2);i++){

        let entry = entries[i].cloneNode(true);

        // If multiple ETA entries → latest becomes Revised ETA
        if(i === 0 && entries.length > 1){

            let title = entry.querySelector("b");

            if(title){
                title.innerText = "Revised ETA";
            }
        }

        visible_entries.push(entry.outerHTML);
    }

    frm.fields_dict.custom_eta_tracker.$wrapper.html(`
        <style>

        .eta-box{
            border:1px solid #e5e7f1;
            border-radius:8px;
            padding:12px;
            background:#fafbff;
        }

        .eta-entry{
            border-left:4px solid #5e64ff;
            padding:8px;
            margin-bottom:8px;
            background:#f7f8ff;
            border-radius:6px;
            transition: all 0.3s ease;
        }

        .eta-meta{
            font-size:12px;
            color:#777;
        }

        .eta-today-badge{
            background:#ff4d4f;
            color:white;
            font-size:11px;
            padding:2px 6px;
            border-radius:4px;
            margin-right:6px;
        }

        .eta-blink{
            animation: etaBlink 1s infinite;
        }

        @keyframes etaBlink{
            0%{ box-shadow:0 0 0 rgba(255,0,0,0); }
            50%{ box-shadow:0 0 12px rgba(255,0,0,0.9); }
            100%{ box-shadow:0 0 0 rgba(255,0,0,0); }
        }

        </style>

        <div class="eta-box">

            <div style="font-weight:600;margin-bottom:10px;color:#5e64ff;">
                ETA Update History
            </div>

            ${visible_entries.join("")}

        </div>
    `);

    apply_today_indicator(frm);
}


function apply_today_indicator(frm){

    let wrapper = frm.fields_dict.custom_eta_tracker.$wrapper;

    let firstEntry = wrapper.find(".eta-entry").first();

    if(!firstEntry.length) return;

    let eta_value = firstEntry.attr("data-eta");

    if(!eta_value) return;

    let etaDate = frappe.datetime.str_to_obj(eta_value);
    let today = frappe.datetime.get_today();

    let etaDateOnly = frappe.datetime.obj_to_str(etaDate).split(" ")[0];

    if(etaDateOnly === today){

        firstEntry.prepend(`<span class="eta-today-badge">Today ETA</span>`);

        firstEntry.addClass("eta-blink");

    }

}

