            let source_sales_order = frm.doc.items[0].sales_order;

            // If linked to a Sales Order and the PO fields are empty
            if (source_sales_order && (!frm.doc.po_no || !frm.doc.po_date)) {

                // Fetch the updated custom fields from the source Sales Order
                frappe.db.get_value('Sales Order', source_sales_order, 
                    ['custom_deal_po_number', 'custom_deal_po_date']
                ).then(r => {
                    if (r && r.message) {
                        // Set the values in the Sales Invoice
                        if (!frm.doc.po_no && r.message.custom_deal_po_number) {
                            frm.set_value('po_no', r.message.custom_deal_po_number);
                        }
                        if (!frm.doc.po_date && r.message.custom_deal_po_date) {
                            frm.set_value('po_date', r.message.custom_deal_po_date);
                        }
                    }
                });
            }
        }
    }
});
